#[test]
fn saved_character_state_survives_new_session_start_game() {
    let config = SimulationConfig::default();
    let mut first = SimulationSession::new(config.clone());
    let _ = first.handle_packet(ClientPacket::Login {
        account_id: "demo".to_string(),
        password: "demo".to_string(),
    });
    let _ = first.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_player_position(&mut first, Point { x: 333, y: 267 });
    let _ = first.attack(3002);
    first.save_active_character();
    let saved_snapshot = first.world_snapshot();
    let saved_weapon_dura = saved_snapshot
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("saved weapon")
        .durability_current;

    let mut second = SimulationSession::new(config);
    let _ = second.handle_packet(ClientPacket::Login {
        account_id: "demo".to_string(),
        password: "demo".to_string(),
    });
    let _ = second.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let restored_snapshot = second.world_snapshot();
    let restored_player = restored_snapshot
        .entities
        .iter()
        .find(|entity| entity.kind == crate::WorldEntityKind::SelfPlayer)
        .expect("restored self player");
    let restored_weapon_dura = restored_snapshot
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("restored weapon")
        .durability_current;

    assert_eq!(restored_player.x, 333);
    assert_eq!(restored_player.y, 267);
    assert_eq!(restored_weapon_dura, saved_weapon_dura);
    assert!(restored_weapon_dura < 18);
}

#[test]
fn online_session_refreshes_admin_delivered_mail_before_save() {
    let config = SimulationConfig::default();
    let mut session = SimulationSession::new(config.clone());
    let _ = session.handle_packet(ClientPacket::Login {
        account_id: "demo".to_string(),
        password: "demo".to_string(),
    });
    let _ = session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    assert!(session.world_snapshot().stage5_systems.mail.is_empty());

    deliver_stage5_system_mail(
        &config,
        Stage5MailDelivery {
            target_kind: Stage5MailTargetKind::Character,
            target_id: "Scout".to_string(),
            from: "GM System".to_string(),
            subject: "Online Grant".to_string(),
            body: "Refresh into the active session.".to_string(),
            gold: 777,
            items: Vec::new(),
        },
    )
    .expect("admin mail should deliver to account store");

    assert!(session.refresh_active_external_mail());
    let snapshot = session.world_snapshot();
    assert!(snapshot.stage5_systems.mail.iter().any(|mail| {
        mail.subject == "Online Grant" && mail.gold == 777 && !mail.claimed && !mail.deleted
    }));
    session.save_active_character();

    let mut reloaded = SimulationSession::new(config);
    let _ = reloaded.handle_packet(ClientPacket::Login {
        account_id: "demo".to_string(),
        password: "demo".to_string(),
    });
    let _ = reloaded.handle_packet(ClientPacket::StartGame { character_index: 0 });
    assert!(reloaded
        .world_snapshot()
        .stage5_systems
        .mail
        .iter()
        .any(|mail| mail.subject == "Online Grant" && mail.gold == 777));
}

