#[test]
fn ai0_default_monsterobject_uses_imported_melee_baseline() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 322, y: 277 };
    let yob_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    let yob_object_id = 98_954_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let yob = spawn_crystal_monster_for_test(
        &mut session,
        yob_object_id,
        "Yob",
        yob_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(yob);
        let agent = entry.get::<MonsterAgent>().expect("yob agent");
        assert_eq!(agent.ai, 0);
        assert_eq!(agent.view_range, 7);
        assert!(super::monster_in_attack_range(
            agent,
            &yob_position,
            &player_origin
        ));
        assert!(!super::monster_prefers_ranged_when_not_adjacent(
            agent,
            &yob_position,
            &player_origin
        ));
        let mut agent = entry.get_mut::<MonsterAgent>().expect("yob agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_attack = false;
    let mut saw_struck = false;
    for _ in 0..6 {
        let packets = session.tick();
        saw_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == yob_object_id
                        && info.attack_type == 0
                        && info.direction == MirDirection::Left
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == yob_object_id
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info } if info.object_id == yob_object_id
            )
        }));
        if saw_attack
            && saw_struck
            && before_hp - session.world_snapshot().player_hp.expect("player hp") > 7
        {
            break;
        }
    }

    assert!(saw_attack);
    assert!(saw_struck);
    assert!(
        session.world_snapshot().player_hp.expect("player hp") < before_hp,
        "AI0 default MonsterObject should use imported Crystal DC melee damage"
    );
}

