#[test]
fn reviving_zombie_revives_twice_with_reduced_health() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let zombie_object_id = 98_952_u32;
    set_player_position(&mut session, player_origin.clone());
    let zombie = spawn_crystal_monster_for_test(
        &mut session,
        zombie_object_id,
        "Zombie3",
        Point {
            x: player_origin.x + 1,
            y: player_origin.y,
        },
        MirDirection::Left,
        true,
    );
    sync_visible_objects(&mut session);

    let max_hp = session
        .app
        .world()
        .entity(zombie)
        .get::<MonsterVitals>()
        .expect("reviving zombie vitals")
        .max_hp;

    for (revival_index, expected_hp) in [(1_u8, max_hp * 75 / 100), (2, max_hp * 50 / 100)] {
        let current_tick = runtime_tick(session.app.world());
        let mut death_packets = Vec::new();
        assert!(super::damage_monster_entity(
            session.app.world_mut(),
            zombie,
            i32::MAX,
            current_tick,
            &mut death_packets,
        ));
        assert!(packet_has_object_died(&death_packets, zombie_object_id));

        let mut revive_packets = Vec::new();
        for _ in 0..=super::REVIVING_ZOMBIE_REVIVE_DELAY_TICKS {
            let packets = session.tick();
            if packets.iter().any(|packet| {
                matches!(
                    packet,
                    ServerPacket::ObjectRevived { info } if info.object_id == zombie_object_id
                )
            }) {
                revive_packets = packets;
                break;
            }
        }

        assert!(revive_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectRevived { info } if info.object_id == zombie_object_id
        )));
        let vitals = session
            .app
            .world()
            .entity(zombie)
            .get::<MonsterVitals>()
            .expect("revived zombie vitals");
        assert_eq!(vitals.hp, expected_hp.max(1));
        let ai_state = session
            .app
            .world()
            .entity(zombie)
            .get::<MonsterAiState>()
            .copied()
            .expect("reviving zombie ai state");
        assert_eq!(ai_state.extra_byte, revival_index);
    }

    let current_tick = runtime_tick(session.app.world());
    let mut final_death_packets = Vec::new();
    assert!(super::damage_monster_entity(
        session.app.world_mut(),
        zombie,
        i32::MAX,
        current_tick,
        &mut final_death_packets,
    ));
    for _ in 0..=super::REVIVING_ZOMBIE_REVIVE_DELAY_TICKS {
        let packets = session.tick();
        assert!(!packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectRevived { info } if info.object_id == zombie_object_id
        )));
    }
}

