#[test]
fn axe_skeleton_moves_closer_before_fear_window_attack() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let (player_origin, monster_position, expected_step) = (240..460)
        .find_map(|y| {
            (240..460).find_map(|x| {
                let player_position = Point { x, y };
                let monster_position = Point { x: x + 6, y };
                let expected_step = Point { x: x + 5, y };
                (can_occupy(session.app.world(), player_position.clone(), Some(player))
                    && can_occupy(session.app.world(), monster_position.clone(), None)
                    && can_occupy(session.app.world(), expected_step.clone(), None))
                .then_some((player_position, monster_position, expected_step))
            })
        })
        .expect("test should find an open AxeSkeleton close lane");
    let monster_object_id = 98_883_u32;
    let current_tick = runtime_tick(session.app.world());

    set_player_position(&mut session, player_origin.clone());
    let monster_entity = session
        .app
        .world_mut()
        .spawn((
            ObjectId(monster_object_id),
            DisplayName::literal("Axe Skeleton Fear Close Test"),
            Position(monster_position),
            Facing(MirDirection::Left),
            Monster,
            MonsterVitals { hp: 50, max_hp: 50 },
            MonsterAgent {
                image: 43,
                dead: false,
                patrol_origin: player_origin,
                ai: 8,
                disposition: WorldEntityDisposition::Hostile,
                hostile_to_player: true,
                tracking_player: true,
                view_range: 7,
                can_wander: true,
                move_interval_ticks: 1,
                attack_interval_ticks: 20,
                next_move_tick: current_tick,
                next_attack_tick: current_tick,
                route: Vec::new(),
                route_index: 0,
                route_waiting: false,
                next_route_tick: current_tick,
            },
        ))
        .id();
    sync_visible_objects(&mut session);

    let move_packets = session.tick();
    assert!(
        move_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectWalk { movement }
                if movement.object_id == monster_object_id
                    && movement.position == expected_step
                    && movement.direction == MirDirection::Left
        )),
        "packets: {:?}",
        trace_server_packets(&move_packets)
    );
    assert!(!move_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectRangeAttack { info } if info.object_id == monster_object_id
    )));
    assert!(
        session
            .app
            .world()
            .entity(monster_entity)
            .get::<MonsterAiState>()
            .expect("axe skeleton ai state")
            .next_state_tick
            > current_tick
    );

    let attack_packets = session.tick();
    assert!(attack_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectRangeAttack { info }
            if info.object_id == monster_object_id && info.target_id == player_object_id
    )));
}

