#[test]
fn harvest_monster_skips_death_drops_and_harvests_corpse_like_crystal() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let training_dummy_object_id = 3001_u32;
    let dummy = entity_by_object_id(session.app.world(), training_dummy_object_id)
        .expect("training dummy entity");
    {
        let mut entry = session.app.world_mut().entity_mut(dummy);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("dummy agent");
        agent.ai = 9;
        agent.can_wander = false;
        agent.hostile_to_player = false;
        agent.tracking_player = false;
        drop(agent);
        entry.insert(super::initial_harvest_monster_state(9).expect("harvest state"));
    }

    set_player_position(&mut session, Point { x: 337, y: 273 });
    let death_packets = attack_until_monster_dies(&mut session, training_dummy_object_id, 10);
    assert!(packet_has_object_died(
        &death_packets,
        training_dummy_object_id
    ));
    assert!(!death_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectItem { .. } | ServerPacket::ObjectGold { .. }
        )
    }));
    assert!(!session
        .world_snapshot()
        .ground_drops
        .iter()
        .any(|drop| drop.name == "Training Splinter"));

    let first_harvest = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });
    assert!(first_harvest.iter().any(|packet| {
        matches!(packet, ServerPacket::ObjectHarvest { movement } if movement.object_id == 1000)
    }));
    assert!(!first_harvest.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectHarvested { movement }
                if movement.object_id == training_dummy_object_id
        )
    }));

    let second_harvest = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });
    assert!(!second_harvest.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectHarvested { movement }
                if movement.object_id == training_dummy_object_id
        )
    }));
    assert!(!session
        .world_snapshot()
        .inventory_items
        .iter()
        .any(|item| item.key == "training-splinter"));

    let third_harvest = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });
    assert!(third_harvest.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectHarvested { movement }
                if movement.object_id == training_dummy_object_id
        )
    }));
    assert!(third_harvest
        .iter()
        .any(|packet| matches!(packet, ServerPacket::GainedItem { item } if item.item_index == 6)));
    assert!(!third_harvest
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));
    assert!(session
        .world_snapshot()
        .inventory_items
        .iter()
        .any(|item| item.key == "training-splinter"));
    assert!(
        session
            .app
            .world()
            .entity(dummy)
            .get::<super::HarvestMonsterState>()
            .expect("harvest state")
            .harvested
    );
}

#[test]
fn no_drop_monster_map_rule_makes_harvest_corpse_find_nothing() {
    let mut config = SimulationConfig::default();
    config.map_drop_rules.push(MapDropRuleRecord {
        map_file_name: "0.map".to_string(),
        no_town_teleport: false,
        no_escape: false,
        no_random: false,
        no_drug: false,
        no_reincarnation: false,
        no_throw_item: false,
        no_drop_player: false,
        no_drop_monster: true,
        no_mount: false,
        no_hero: false,
        need_bridle: false,
    });
    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let training_dummy_object_id = 3001_u32;
    let dummy = entity_by_object_id(session.app.world(), training_dummy_object_id)
        .expect("training dummy entity");
    {
        let mut entry = session.app.world_mut().entity_mut(dummy);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("dummy agent");
        agent.ai = 9;
        agent.can_wander = false;
        agent.hostile_to_player = false;
        agent.tracking_player = false;
        drop(agent);
        entry.insert(super::initial_harvest_monster_state(9).expect("harvest state"));
    }

    set_player_position(&mut session, Point { x: 337, y: 273 });
    let death_packets = attack_until_monster_dies(&mut session, training_dummy_object_id, 10);
    assert!(packet_has_object_died(
        &death_packets,
        training_dummy_object_id
    ));

    let first_harvest = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });
    assert!(first_harvest.iter().any(
            |packet| matches!(packet, ServerPacket::ObjectHarvest { movement } if movement.object_id == 1000)
        ));
    assert!(!first_harvest.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectHarvested { movement }
            if movement.object_id == training_dummy_object_id
    )));

    let second_harvest = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });
    assert!(second_harvest.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectHarvested { movement }
            if movement.object_id == training_dummy_object_id
    )));
    assert!(second_harvest.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            message
        } if message
            == &super::localized_text_or_fallback(
                super::LanguageCode::English,
                "server.NothingWasFound",
                "server.NothingWasFound",
            )
    )));
    assert!(!second_harvest
        .iter()
        .any(|packet| matches!(packet, ServerPacket::GainedItem { .. })));
    assert!(session
        .world_snapshot()
        .inventory_items
        .iter()
        .all(|item| item.key != "training-splinter"));
}

#[test]
fn deer_is_passive_and_requires_five_harvest_passes() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let (player_origin, deer_position) = (240..460)
        .find_map(|y| {
            (240..460).find_map(|x| {
                let player = Point { x, y };
                let deer = Point { x: x + 1, y };
                (can_occupy(session.app.world(), player.clone(), None)
                    && can_occupy(session.app.world(), deer.clone(), None))
                .then_some((player, deer))
            })
        })
        .expect("test should find an occupiable harvest line");
    let deer_object_id = 98_912_u32;
    set_player_position(&mut session, player_origin.clone());
    assert!(!super::monster_targets_players(2));
    assert_eq!(
        super::initial_harvest_monster_state(2)
            .expect("deer harvest state")
            .remaining_skin_count,
        super::DEER_SKIN_COUNT
    );

    let deer = spawn_crystal_monster_for_test(
        &mut session,
        deer_object_id,
        "Deer",
        deer_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(deer);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("deer agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.next_attack_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    for _ in 0..2 {
        let packets = session.tick();
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == deer_object_id
            )
        }));
    }

    let death_tick = runtime_tick(session.app.world());
    let mut death_packets = Vec::new();
    assert!(super::damage_monster_entity(
        session.app.world_mut(),
        deer,
        i32::MAX,
        death_tick,
        &mut death_packets,
    ));
    assert!(packet_has_object_died(&death_packets, deer_object_id));
    assert_eq!(
        entity_position(session.app.world(), deer).expect("deer position"),
        deer_position
    );
    assert!(
        session
            .app
            .world()
            .entity(deer)
            .get::<MonsterAgent>()
            .expect("deer agent")
            .dead
    );
    let expected_venison_quality =
        super::crystal_harvest_quality(session.app.world(), deer_object_id);

    let mut expected_venison_dura = None;
    for harvest_index in 1..=super::DEER_SKIN_COUNT {
        let generated_venison_dura = super::crystal_drop_item_current_durability(
            8000,
            runtime_tick(session.app.world()),
            deer_object_id,
            0,
        )
        .saturating_add(expected_venison_quality);
        let packets = session.handle_packet(ClientPacket::Harvest {
            direction: MirDirection::Right,
        });
        let harvested = packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectHarvested { movement }
                    if movement.object_id == deer_object_id
            )
        });
        let state = session
            .app
            .world()
            .entity(deer)
            .get::<super::HarvestMonsterState>()
            .copied();
        assert_eq!(
            harvested, false,
            "harvest {harvest_index}, state {state:?}, packets {packets:?}"
        );
        if harvest_index == super::DEER_SKIN_COUNT {
            expected_venison_dura = Some(generated_venison_dura);
            let state = state.expect("harvest state after final skin pass");
            assert_eq!(state.remaining_skin_count, 0);
            assert!(state.drops_ready);
            assert!(!state.harvested);
            assert!(!packets
                .iter()
                .any(|packet| matches!(packet, ServerPacket::GainedItem { .. })));
        }
    }

    let transfer_packets = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });
    assert!(transfer_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectHarvested { movement }
                if movement.object_id == deer_object_id
        )
    }));
    assert!(transfer_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GainedItem { item }
            if item.item_index == 853
                && item.count == 1
                && item.current_dura == expected_venison_dura.expect("generated dura")
                && item.max_dura == 8000
                && item.identified
    )));
    assert!(session
        .world_snapshot()
        .inventory_items
        .iter()
        .any(|item| item.key == "crystal-item-853" && item.name == "Venison"));
}

#[test]
fn runaway_deer_flees_from_player_without_attacking() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let (player_origin, deer_position, expected_step) = (240..460)
        .find_map(|y| {
            (240..460).find_map(|x| {
                let player_position = Point { x, y };
                let deer_position = Point { x: x + 1, y };
                let expected_step = Point { x: x + 2, y };
                (can_occupy(session.app.world(), player_position.clone(), Some(player))
                    && can_occupy(session.app.world(), deer_position.clone(), None)
                    && can_occupy(session.app.world(), expected_step.clone(), None))
                .then_some((player_position, deer_position, expected_step))
            })
        })
        .expect("test should find an open runaway deer lane");
    let deer_object_id = 98_915_u32;
    set_player_position(&mut session, player_origin);
    let deer = spawn_crystal_monster_for_test(
        &mut session,
        deer_object_id,
        "Deer",
        deer_position,
        MirDirection::Left,
        false,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(deer);
        let mut ai_state = entry.get_mut::<MonsterAiState>().expect("deer ai state");
        ai_state.mode = true;
        let mut agent = entry.get_mut::<MonsterAgent>().expect("deer agent");
        agent.tracking_player = false;
        agent.move_interval_ticks = 1;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let packets = session.tick();
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectWalk { movement }
            if movement.object_id == deer_object_id
                && movement.position == expected_step
                && movement.direction == MirDirection::Right
    )));
    assert!(!packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info } if info.object_id == deer_object_id
    )));
    assert!(
        session
            .app
            .world()
            .entity(deer)
            .get::<MonsterAgent>()
            .expect("deer agent")
            .tracking_player
    );
}

#[test]
fn hen_is_passive_and_requires_two_skin_passes_then_transfer() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let (player_origin, hen_position) = (240..460)
        .find_map(|y| {
            (240..460).find_map(|x| {
                let player = Point { x, y };
                let hen = Point { x: x + 1, y };
                (can_occupy(session.app.world(), player.clone(), None)
                    && can_occupy(session.app.world(), hen.clone(), None))
                .then_some((player, hen))
            })
        })
        .expect("test should find an occupiable harvest line");
    let hen_object_id = 98_913_u32;
    set_player_position(&mut session, player_origin);
    assert!(!super::monster_targets_players(1));
    assert_eq!(
        super::initial_harvest_monster_state(1)
            .expect("hen harvest state")
            .remaining_skin_count,
        super::HARVEST_MONSTER_SKIN_COUNT
    );

    let hen = spawn_crystal_monster_for_test(
        &mut session,
        hen_object_id,
        "Hen",
        hen_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(hen);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("hen agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.next_attack_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    for _ in 0..2 {
        let packets = session.tick();
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == hen_object_id
            )
        }));
    }

    let death_tick = runtime_tick(session.app.world());
    let mut death_packets = Vec::new();
    assert!(super::damage_monster_entity(
        session.app.world_mut(),
        hen,
        i32::MAX,
        death_tick,
        &mut death_packets,
    ));
    assert!(packet_has_object_died(&death_packets, hen_object_id));
    assert_eq!(
        entity_position(session.app.world(), hen).expect("hen position"),
        hen_position
    );

    let mut expected_chicken_dura = None;
    for harvest_index in 1..=super::HARVEST_MONSTER_SKIN_COUNT {
        let generated_chicken_dura = super::crystal_drop_item_current_durability(
            4000,
            runtime_tick(session.app.world()),
            hen_object_id,
            0,
        );
        let packets = session.handle_packet(ClientPacket::Harvest {
            direction: MirDirection::Right,
        });
        let harvested = packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectHarvested { movement }
                    if movement.object_id == hen_object_id
            )
        });
        assert_eq!(
            harvested, false,
            "harvest {harvest_index}, packets {packets:?}"
        );
        if harvest_index == super::HARVEST_MONSTER_SKIN_COUNT {
            expected_chicken_dura = Some(generated_chicken_dura);
            let state = session
                .app
                .world()
                .entity(hen)
                .get::<super::HarvestMonsterState>()
                .copied()
                .expect("hen harvest state after final skin pass");
            assert_eq!(state.remaining_skin_count, 0);
            assert!(state.drops_ready);
            assert!(!state.harvested);
            assert!(!packets
                .iter()
                .any(|packet| matches!(packet, ServerPacket::GainedItem { .. })));
        }
    }

    let transfer_packets = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });
    assert!(transfer_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectHarvested { movement }
                if movement.object_id == hen_object_id
        )
    }));
    assert!(transfer_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GainedItem { item }
            if item.item_index == 850
                && item.count == 1
                && item.current_dura == expected_chicken_dura.expect("generated dura")
                && item.max_dura == 4000
                && item.identified
    )));
    assert!(session
        .world_snapshot()
        .inventory_items
        .iter()
        .any(|item| item.key == "crystal-item-850" && item.name == "Chicken"));
}

#[test]
fn harvest_keeps_pending_drops_when_bag_is_full_and_transfers_later() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let (player_origin, hen_position) = (240..460)
        .find_map(|y| {
            (240..460).find_map(|x| {
                let player = Point { x, y };
                let hen = Point { x: x + 1, y };
                (can_occupy(session.app.world(), player.clone(), None)
                    && can_occupy(session.app.world(), hen.clone(), None))
                .then_some((player, hen))
            })
        })
        .expect("test should find an occupiable harvest line");
    let hen_object_id = 98_919_u32;
    set_player_position(&mut session, player_origin);
    let hen = spawn_crystal_monster_for_test(
        &mut session,
        hen_object_id,
        "Hen",
        hen_position.clone(),
        MirDirection::Left,
        true,
    );
    sync_visible_objects(&mut session);

    let death_tick = runtime_tick(session.app.world());
    let mut death_packets = Vec::new();
    assert!(super::damage_monster_entity(
        session.app.world_mut(),
        hen,
        i32::MAX,
        death_tick,
        &mut death_packets,
    ));
    assert!(packet_has_object_died(&death_packets, hen_object_id));

    for _ in 0..super::HARVEST_MONSTER_SKIN_COUNT {
        let packets = session.handle_packet(ClientPacket::Harvest {
            direction: MirDirection::Right,
        });
        assert!(!packets
            .iter()
            .any(|packet| matches!(packet, ServerPacket::ObjectHarvested { .. })));
    }
    assert_eq!(
        session
            .app
            .world()
            .entity(hen)
            .get::<super::PendingHarvestDrops>()
            .expect("pending hen drops")
            .drops
            .len(),
        1
    );

    fill_all_bag_slots(&mut session);
    let blocked_packets = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });
    assert!(blocked_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            message
        } if message
            == &super::localized_text_or_fallback(
                super::LanguageCode::English,
                "server.YouCannotCarryAnymore",
                "server.YouCannotCarryAnymore",
            )
    )));
    assert!(!blocked_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ObjectHarvested { .. })));
    assert!(session
        .app
        .world()
        .entity(hen)
        .get::<super::PendingHarvestDrops>()
        .is_some());

    session
        .app
        .world_mut()
        .resource_mut::<InventoryResource>()
        .inventory_items
        .pop();
    let transfer_packets = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });

    assert!(transfer_packets.iter().any(
        |packet| matches!(packet, ServerPacket::GainedItem { item } if item.item_index == 850)
    ));
    assert!(transfer_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectHarvested { movement }
                if movement.object_id == hen_object_id
        )
    }));
    assert!(session
        .app
        .world()
        .entity(hen)
        .get::<super::PendingHarvestDrops>()
        .is_none());
}

#[test]
fn harvest_skips_owner_blocked_corpse_and_harvests_next_candidate() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let player_origin = Point { x: 330, y: 270 };
    set_player_position(&mut session, player_origin.clone());

    let blocked = spawn_crystal_monster_for_test(
        &mut session,
        98_940,
        "Hen",
        Point { x: 331, y: 270 },
        MirDirection::Left,
        true,
    );
    let candidate = spawn_crystal_monster_for_test(
        &mut session,
        98_941,
        "Hen",
        Point { x: 331, y: 271 },
        MirDirection::Left,
        true,
    );
    for (entity, ownership) in [(blocked, Some(9001_u32)), (candidate, None)] {
        let mut entry = session.app.world_mut().entity_mut(entity);
        entry.insert(MonsterVitals { hp: 0, max_hp: 1 });
        {
            let mut agent = entry.get_mut::<MonsterAgent>().expect("hen agent");
            agent.dead = true;
        }
        if let Some(owner_object_id) = ownership {
            entry.insert(super::HarvestOwnership { owner_object_id });
        }
    }

    let packets = session.handle_packet(ClientPacket::Harvest {
        direction: MirDirection::Right,
    });

    assert!(!packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message.contains("carcasses")
    )));
    assert_eq!(
        session
            .app
            .world()
            .entity(blocked)
            .get::<super::HarvestMonsterState>()
            .map(|state| state.remaining_skin_count)
            .unwrap_or(super::HARVEST_MONSTER_SKIN_COUNT),
        super::HARVEST_MONSTER_SKIN_COUNT
    );
    assert_eq!(
        session
            .app
            .world()
            .entity(candidate)
            .get::<super::HarvestMonsterState>()
            .expect("candidate state")
            .remaining_skin_count,
        super::HARVEST_MONSTER_SKIN_COUNT - 1
    );
}

