#[test]
fn cannibal_tentacles_adjacent_halfmoon_branch_poisons_and_fans_out() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let (player_origin, tentacles_position, ally_position) = (320..380)
        .flat_map(|x| (278..312).map(move |y| Point { x, y }))
        .find_map(|point| {
            let tentacles_position = Point {
                x: point.x + 1,
                y: point.y,
            };
            let ally_position = Point {
                x: point.x,
                y: point.y - 1,
            };
            (can_occupy(session.app.world(), point.clone(), Some(player))
                && can_occupy(session.app.world(), tentacles_position.clone(), None)
                && can_occupy(session.app.world(), ally_position.clone(), None))
            .then_some((point, tentacles_position, ally_position))
        })
        .expect("test should find an open CannibalTentacles halfmoon layout");
    let tentacles_object_id = 99_910_u32;
    let ally_object_id = 99_911_u32;
    set_current_player_hp(&mut session, 500);
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin);
    let tentacles = spawn_crystal_monster_for_test(
        &mut session,
        tentacles_object_id,
        "CannibalTentacles",
        tentacles_position,
        MirDirection::Left,
        true,
    );
    let ally = spawn_crystal_monster_for_test(
        &mut session,
        ally_object_id,
        "BugBat",
        ally_position,
        MirDirection::Left,
        false,
    );
    let current_tick = runtime_tick(session.app.world());
    let branch_tick = current_tick + (5 - current_tick % 5);
    {
        let mut entry = session.app.world_mut().entity_mut(tentacles);
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("cannibal tentacles agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = branch_tick;
        agent.next_move_tick = branch_tick;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(ally);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
        agent.can_wander = false;
        agent.tracking_player = false;
    }
    let ally_hp_before = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    sync_visible_objects(&mut session);

    let mut branch_packets = Vec::new();
    while runtime_tick(session.app.world()) < branch_tick {
        branch_packets = session.tick();
    }
    assert!(branch_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == tentacles_object_id
                    && info.attack_type == 1
                    && info.direction == MirDirection::Left
        )
    }));
    assert!(!branch_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info }
                if info.object_id == tentacles_object_id && info.target_id == player_object_id
        )
    }));

    let damage_packets = session.tick();
    assert!(damage_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == tentacles_object_id
        )
    }));
    assert!(damage_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectStruck { info }
                if info.object_id == ally_object_id && info.attacker_id == tentacles_object_id
        )
    }));
    assert!(session
        .world_snapshot()
        .active_buffs
        .iter()
        .any(|buff| buff.key == super::TOXIC_GHOUL_GREEN_POISON_BUFF_KEY));
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 100,
        "CannibalTentacles halfmoon should use Crystal's fixed 500-damage branch"
    );
    let ally_hp_after = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    assert!(
        ally_hp_after < ally_hp_before,
        "CannibalTentacles halfmoon should hit adjacent opposing monsters in the arc"
    );
}

#[test]
fn jar2_uses_crystal_range_packet_without_zero_mc_damage() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let jar_object_id = 98_906_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let jar = spawn_crystal_monster_for_test(
        &mut session,
        jar_object_id,
        "Jar2",
        Point {
            x: player_origin.x + 4,
            y: player_origin.y,
        },
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(jar);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("jar2 agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 100;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_range_attack = false;
    for _ in 0..4 {
        let packets = session.tick();
        saw_range_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == jar_object_id && info.target_id == 1000
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement } if movement.object_id == jar_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == jar_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == jar_object_id
            )
        }));
    }

    assert!(saw_range_attack);
    assert_eq!(
        session.world_snapshot().player_hp.expect("player hp"),
        before_hp
    );
}

#[test]
fn jar2_adjacent_melee_branch_uses_crystal_random_dc_path() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let player_origin = Point { x: 900, y: 900 };
    let jar_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    let jar_object_id = 99_920_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin);
    let jar = spawn_crystal_monster_for_test(
        &mut session,
        jar_object_id,
        "Jar2",
        jar_position,
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    let branch_tick = current_tick + (3 - current_tick % 3);
    {
        let mut entry = session.app.world_mut().entity_mut(jar);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("jar2 agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = branch_tick;
        agent.next_move_tick = branch_tick;
    }
    sync_visible_objects(&mut session);

    let mut branch_packets = Vec::new();
    while runtime_tick(session.app.world()) < branch_tick {
        branch_packets = session.tick();
    }
    assert!(branch_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == jar_object_id
                    && info.attack_type == 0
                    && info.direction == MirDirection::Left
        )
    }));
    assert!(!branch_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectRangeAttack { info }
                if info.object_id == jar_object_id && info.target_id == player_object_id
        )
    }));

    let damage_packets = session.tick();
    assert!(damage_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == jar_object_id
        )
    }));
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "Jar2 adjacent melee branch should use imported Crystal DC damage"
    );
}

