#[test]
fn red_thunder_zuma_wakes_and_uses_crystal_ranged_attack() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let zuma_position = Point {
        x: player_origin.x + 2,
        y: player_origin.y,
    };
    let zuma_object_id = 98_914_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let zuma = spawn_crystal_monster_for_test(
        &mut session,
        zuma_object_id,
        "RedThunderZuma",
        zuma_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(zuma);
        let agent = entry.get::<MonsterAgent>().expect("red thunder zuma agent");
        assert!(super::monster_in_attack_range(
            agent,
            &zuma_position,
            &Point {
                x: zuma_position.x - 9,
                y: zuma_position.y,
            }
        ));
        assert!(!super::monster_in_attack_range(
            agent,
            &zuma_position,
            &Point {
                x: zuma_position.x - 10,
                y: zuma_position.y,
            }
        ));
        let ai_state = entry
            .get::<MonsterAiState>()
            .copied()
            .expect("red thunder zuma ai state");
        assert!(ai_state.extra);

        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("red thunder zuma agent");
        agent.can_wander = true;
        agent.tracking_player = false;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_show = false;
    let mut saw_range_attack = false;
    let mut saw_struck = false;
    for _ in 0..8 {
        let packets = session.tick();
        saw_show |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectShow { object_id } if *object_id == zuma_object_id
            )
        });
        saw_range_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == zuma_object_id
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == zuma_object_id
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == zuma_object_id
            )
        }));
        if saw_show && saw_range_attack && saw_struck {
            break;
        }
    }

    assert!(saw_show);
    assert!(saw_range_attack);
    assert!(saw_struck);
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "RedThunderZuma should use imported Crystal DC damage instead of generic damage"
    );
}

