#[test]
fn great_fox_spirit_toggles_nearby_guardian_rock_active_state() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let fox_position = Point {
        x: player_origin.x + 4,
        y: player_origin.y,
    };
    let rock_position = Point {
        x: fox_position.x + 2,
        y: fox_position.y,
    };
    set_player_position(&mut session, player_origin);
    let fox = spawn_crystal_monster_for_test(
        &mut session,
        99_956_u32,
        "GreatFoxSpirit",
        fox_position,
        MirDirection::Left,
        false,
    );
    let rock = spawn_crystal_monster_for_test(
        &mut session,
        99_957_u32,
        "GuardianRock",
        rock_position,
        MirDirection::Up,
        true,
    );
    {
        let mut rock_entry = session.app.world_mut().entity_mut(rock);
        let mut rock_state = rock_entry
            .get::<MonsterAiState>()
            .copied()
            .expect("guardian rock ai state");
        rock_state.mode = false;
        rock_entry.insert(rock_state);
    }
    sync_visible_objects(&mut session);

    let _ = session.tick();
    {
        let rock_entry = session.app.world().entity(rock);
        let rock_agent = rock_entry
            .get::<MonsterAgent>()
            .expect("guardian rock agent");
        let rock_state = rock_entry
            .get::<MonsterAiState>()
            .expect("guardian rock ai state");
        assert!(rock_state.mode);
        assert!(super::monster_can_attack(rock_agent, rock_state));
    }

    let current_tick = runtime_tick(session.app.world());
    let mut death_packets = Vec::new();
    assert!(super::damage_monster_entity(
        session.app.world_mut(),
        fox,
        i32::MAX,
        current_tick,
        &mut death_packets,
    ));
    {
        let rock_entry = session.app.world().entity(rock);
        let rock_agent = rock_entry
            .get::<MonsterAgent>()
            .expect("guardian rock agent");
        let rock_state = rock_entry
            .get::<MonsterAiState>()
            .expect("guardian rock ai state");
        assert!(!rock_state.mode);
        assert!(!super::monster_can_attack(rock_agent, rock_state));
    }
}

#[test]
fn great_fox_spirit_recalls_far_player_to_nearby_tile() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let fox_position = Point {
        x: player_origin.x + 10,
        y: player_origin.y,
    };
    let recall_tick = runtime_tick(session.app.world()) + 1;
    let fox_object_id = (100_050_u32..100_500_u32)
        .find(|object_id| {
            super::deterministic_chance_roll(recall_tick, *object_id, 502, 10)
                && !super::deterministic_chance_roll(recall_tick, *object_id, 503, 4)
        })
        .expect("test object id should trigger deterministic GreatFoxSpirit recall");
    let player_object_id = current_player_object_id(session.app.world()).expect("player object id");
    set_player_position(&mut session, player_origin.clone());
    let fox = spawn_crystal_monster_for_test(
        &mut session,
        fox_object_id,
        "GreatFoxSpirit",
        fox_position.clone(),
        MirDirection::Left,
        true,
    );
    {
        let mut entry = session.app.world_mut().entity_mut(fox);
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("great fox spirit agent");
        agent.tracking_player = true;
        agent.can_wander = false;
    }
    sync_visible_objects(&mut session);

    let packets = session.tick();
    let recalled_position = player_position(&session);
    assert_ne!(recalled_position, player_origin);
    assert!(tile_distance(&recalled_position, &fox_position) <= 1);
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectWalk { movement }
            if movement.object_id == player_object_id
                && movement.position == recalled_position
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectTeleportOut { object_id, effect_type }
            if *object_id == player_object_id
                && *effect_type == super::GREAT_FOX_SPIRIT_RECALL_TELEPORT_EFFECT
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectTeleportIn { object_id, effect_type }
            if *object_id == player_object_id
                && *effect_type == super::GREAT_FOX_SPIRIT_RECALL_TELEPORT_EFFECT
    )));
    assert_eq!(
        session
            .app
            .world()
            .entity(fox)
            .get::<MonsterAiState>()
            .expect("great fox spirit ai state")
            .next_state_tick,
        recall_tick + super::GREAT_FOX_SPIRIT_RECALL_COOLDOWN_TICKS
    );
}

