#[test]
fn hell_keeper_is_static_and_attacks_from_view_range_without_turning() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let keeper_position = Point {
        x: player_origin.x + 8,
        y: player_origin.y,
    };
    let keeper_object_id = 98_946_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let keeper = spawn_crystal_monster_for_test(
        &mut session,
        keeper_object_id,
        "HellKeeper",
        keeper_position.clone(),
        MirDirection::Up,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(keeper);
        let agent = entry.get::<MonsterAgent>().expect("hell keeper agent");
        assert!(super::monster_in_attack_range(
            agent,
            &keeper_position,
            &player_origin
        ));
        assert!(!super::monster_in_attack_range(
            agent,
            &keeper_position,
            &Point {
                x: keeper_position.x - 15,
                y: keeper_position.y,
            }
        ));
        assert!(!super::monster_can_chase_player(agent));
        assert!(!super::monster_can_follow_route(agent));
        assert!(!super::monster_can_patrol_origin(agent));
        let mut agent = entry.get_mut::<MonsterAgent>().expect("hell keeper agent");
        agent.can_wander = true;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_attack = false;
    let mut saw_struck = false;
    for _ in 0..8 {
        let packets = session.tick();
        saw_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == keeper_object_id
                        && info.attack_type == 0
                        && info.direction == MirDirection::Up
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == keeper_object_id
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info } if info.object_id == keeper_object_id
            )
        }));
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement } if movement.object_id == keeper_object_id
            )
        }));
        if saw_attack && saw_struck {
            break;
        }
    }

    assert_eq!(
        entity_position(session.app.world(), keeper).expect("hell keeper position"),
        keeper_position
    );
    assert_eq!(
        entity_facing(session.app.world(), keeper).expect("hell keeper facing"),
        MirDirection::Up
    );
    assert!(saw_attack);
    assert!(saw_struck);
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "HellKeeper type-0 branch should use imported Crystal DC damage"
    );
}

