#[test]
fn trap_rock_show_spawns_child_rocks_and_paralyzes_target() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = player_position(&session);
    let hidden_position = Point {
        x: player_origin.x + 5,
        y: player_origin.y,
    };
    let rock_object_id = 98_954_u32;
    set_player_position(&mut session, player_origin.clone());
    let rock = spawn_crystal_monster_for_test(
        &mut session,
        rock_object_id,
        "TrapRock",
        hidden_position,
        MirDirection::Left,
        true,
    );

    let mut show_packets = Vec::new();
    for _ in 0..8 {
        let packets = session.tick();
        let saw_parent_show = packets.iter().any(|packet| {
                matches!(packet, ServerPacket::ObjectShow { object_id } if *object_id == rock_object_id)
            });
        show_packets.extend(packets);
        if saw_parent_show {
            break;
        }
    }
    assert!(show_packets.iter().any(|packet| {
        matches!(packet, ServerPacket::ObjectShow { object_id } if *object_id == rock_object_id)
    }));
    assert!(session
        .app
        .world()
        .resource::<BuffResource>()
        .buffs
        .iter()
        .any(|buff| buff.key == super::CAVE_MAGGOT_PARALYSIS_BUFF_KEY));

    let children: Vec<(Entity, u32, Point)> = {
        #[allow(deprecated)]
        session
            .app
            .world()
            .iter_entities()
            .filter_map(|entity| {
                let agent = entity.get::<MonsterAgent>()?;
                if agent.ai != 47 || entity.get::<SummonedMonster>().is_none() {
                    return None;
                }
                let object_id = entity.get::<ObjectId>()?.0;
                let position = entity.get::<Position>()?.0.clone();
                Some((entity.id(), object_id, position))
            })
            .collect()
    };
    assert_eq!(children.len(), 3);
    assert!(children
        .iter()
        .all(|(_, _, position)| tile_distance(position, &player_origin) == 1));
    assert!(children.iter().all(|(child, _, _)| {
        !session
            .app
            .world()
            .entity(*child)
            .get::<MonsterAiState>()
            .expect("trap rock child state")
            .hidden
    }));
    let child_show_count = show_packets
        .iter()
        .filter(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectShow { object_id }
                    if children.iter().any(|(_, child_id, _)| child_id == object_id)
            )
        })
        .count();
    assert_eq!(child_show_count, 3);

    let mut packets = Vec::new();
    let current_tick = runtime_tick(session.app.world());
    assert!(!super::damage_monster_entity(
        session.app.world_mut(),
        children[0].0,
        1,
        current_tick,
        &mut packets,
    ));
    assert!(
        !session
            .app
            .world()
            .entity(rock)
            .get::<MonsterAiState>()
            .expect("parent trap rock state")
            .mode
    );

    let child_ids: Vec<u32> = children
        .iter()
        .map(|(_, object_id, _)| *object_id)
        .collect();
    let mut saw_child_attack = false;
    for _ in 0..4 {
        let packets = session.tick();
        saw_child_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if child_ids.contains(&info.object_id)
            )
        });
        if saw_child_attack {
            break;
        }
    }
    assert!(saw_child_attack);
}

#[test]
fn trap_rock_parent_attack_can_reapply_paralysis() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = player_position(&session);
    let hidden_position = Point {
        x: player_origin.x + 5,
        y: player_origin.y,
    };
    let rock_object_id = 98_955_u32;
    set_player_position(&mut session, player_origin);
    let rock = spawn_crystal_monster_for_test(
        &mut session,
        rock_object_id,
        "TrapRock",
        hidden_position,
        MirDirection::Left,
        true,
    );

    let mut saw_show = false;
    for _ in 0..8 {
        let packets = session.tick();
        saw_show |= packets.iter().any(|packet| {
                matches!(packet, ServerPacket::ObjectShow { object_id } if *object_id == rock_object_id)
            });
        if saw_show {
            break;
        }
    }
    assert!(saw_show);
    session
        .app
        .world_mut()
        .resource_mut::<BuffResource>()
        .buffs
        .retain(|buff| buff.key != super::CAVE_MAGGOT_PARALYSIS_BUFF_KEY);

    let mut attack_tick = runtime_tick(session.app.world()) + 1;
    while !super::deterministic_chance_roll(
        attack_tick,
        rock_object_id,
        47,
        super::TRAP_ROCK_ATTACK_PARALYSIS_CHANCE_DENOMINATOR,
    ) {
        attack_tick += 1;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(rock);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("trap rock agent");
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = attack_tick;
        agent.tracking_player = true;
    }

    let mut saw_parent_attack = false;
    let mut saw_paralysis = false;
    for _ in 0..40 {
        let packets = session.tick();
        saw_parent_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == rock_object_id && info.attack_type == 0
            )
        });
        saw_paralysis |= session
            .app
            .world()
            .resource::<BuffResource>()
            .buffs
            .iter()
            .any(|buff| buff.key == super::CAVE_MAGGOT_PARALYSIS_BUFF_KEY);
        if saw_parent_attack && saw_paralysis {
            break;
        }
    }

    assert!(saw_parent_attack);
    assert!(saw_paralysis);
}

