#[test]
fn frozen_miner_type_one_branch_fans_out_to_adjacent_opposing_monsters() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let miner_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    let ally_position = Point {
        x: miner_position.x,
        y: miner_position.y + 1,
    };
    let miner_object_id = 98_942_u32;
    let ally_object_id = 98_943_u32;
    set_player_position(&mut session, player_origin);
    let miner = spawn_crystal_monster_for_test(
        &mut session,
        miner_object_id,
        "FrozenMiner",
        miner_position,
        MirDirection::Left,
        true,
    );
    let ally = spawn_crystal_monster_for_test(
        &mut session,
        ally_object_id,
        "BugBat",
        ally_position,
        MirDirection::Left,
        false,
    );
    {
        let mut entry = session.app.world_mut().entity_mut(miner);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("frozen miner agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = 1;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(ally);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("ally agent");
        agent.can_wander = false;
        agent.tracking_player = false;
    }
    let ally_hp_before = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    sync_visible_objects(&mut session);

    let attack_packets = session.tick();
    assert!(attack_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == miner_object_id && info.attack_type == 1
        )
    }));

    let damage_packets = session.tick();
    assert!(damage_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == miner_object_id
        )
    }));
    assert!(damage_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectStruck { info }
                if info.object_id == ally_object_id && info.attacker_id == miner_object_id
        )
    }));
    let ally_hp_after = session
        .app
        .world()
        .entity(ally)
        .get::<MonsterVitals>()
        .expect("ally vitals")
        .hp;
    assert!(
        ally_hp_after < ally_hp_before,
        "FrozenMiner type-1 branch should fan out to adjacent opposing monsters"
    );
}

