#[test]
fn frozen_axeman_adjacent_pull_branch_uses_type_two_and_pushes_player() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let player_origin = (320..380)
        .flat_map(|x| (278..312).map(move |y| Point { x, y }))
        .find(|point| {
            let axeman_position = Point {
                x: point.x + 1,
                y: point.y,
            };
            can_occupy(session.app.world(), point.clone(), Some(player))
                && can_occupy(session.app.world(), axeman_position, None)
                && (1..=3).all(|amount| {
                    can_occupy(
                        session.app.world(),
                        Point {
                            x: point.x - amount,
                            y: point.y,
                        },
                        Some(player),
                    )
                })
        })
        .expect("test should find an open FrozenAxeman push lane");
    let axeman_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    let axeman_object_id = 98_941_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let axeman = spawn_crystal_monster_for_test(
        &mut session,
        axeman_object_id,
        "FrozenAxeman",
        axeman_position,
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(axeman);
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("frozen axeman agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let attack_packets = session.tick();
    assert!(attack_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == axeman_object_id
                    && info.attack_type == 2
                    && info.direction == MirDirection::Left
        )
    }));
    let pushed_position = attack_packets.iter().find_map(|packet| match packet {
        ServerPacket::ObjectWalk { movement } if movement.object_id == player_object_id => {
            Some(movement.position.clone())
        }
        _ => None,
    });
    assert_eq!(
        pushed_position,
        Some(Point {
            x: player_origin.x - 3,
            y: player_origin.y,
        })
    );
    assert!(!attack_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == axeman_object_id
        )
    }));
    assert!(
        session
            .app
            .world()
            .entity(axeman)
            .get::<MonsterAiState>()
            .expect("frozen axeman ai state")
            .next_state_tick
            > current_tick
    );

    let damage_packets = session.tick();
    assert!(damage_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == axeman_object_id
        )
    }));
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "FrozenAxeman pull branch should still apply imported Crystal DC damage"
    );
}

