#[test]
fn crystal_spider_uses_three_tile_line_attack_and_green_poison() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let spider_position = Point {
        x: player_origin.x + 3,
        y: player_origin.y,
    };
    let spider_object_id = 98_924_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let spider = spawn_crystal_monster_for_test(
        &mut session,
        spider_object_id,
        "CrystalSpider",
        spider_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(spider);
        let agent = entry.get::<MonsterAgent>().expect("crystal spider agent");
        assert!(super::monster_in_attack_range(
            agent,
            &spider_position,
            &player_origin
        ));
        assert!(super::monster_in_attack_range(
            agent,
            &spider_position,
            &Point {
                x: spider_position.x - 3,
                y: spider_position.y + 3,
            }
        ));
        assert!(!super::monster_in_attack_range(
            agent,
            &spider_position,
            &Point {
                x: spider_position.x - 2,
                y: spider_position.y + 3,
            }
        ));
        let mut agent = entry
            .get_mut::<MonsterAgent>()
            .expect("crystal spider agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_attack = false;
    let mut saw_struck = false;
    for _ in 0..80 {
        let packets = session.tick();
        saw_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info }
                    if info.object_id == spider_object_id
                        && info.direction == MirDirection::Left
                        && info.attack_type == 1
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == spider_object_id
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectRangeAttack { info }
                    if info.object_id == spider_object_id
            )
        }));
        if session
            .world_snapshot()
            .active_buffs
            .iter()
            .any(|buff| buff.key == super::TOXIC_GHOUL_GREEN_POISON_BUFF_KEY)
        {
            break;
        }
    }

    assert!(saw_attack);
    assert!(saw_struck);
    assert!(session.world_snapshot().player_hp.expect("player hp") < before_hp);
    assert!(session
        .world_snapshot()
        .active_buffs
        .iter()
        .any(|buff| buff.key == super::TOXIC_GHOUL_GREEN_POISON_BUFF_KEY));
}

