fn turtle_grass_wakes_and_attacks_from_crystal_two_tile_range() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let grass_position = Point {
        x: player_origin.x + 2,
        y: player_origin.y,
    };
    let grass_object_id = 98_908_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let grass = spawn_crystal_monster_for_test(
        &mut session,
        grass_object_id,
        "TurtleGrass",
        grass_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    {
        let mut entry = session.app.world_mut().entity_mut(grass);
        let agent = entry.get::<MonsterAgent>().expect("turtle grass agent");
        assert!(super::monster_in_attack_range(
            agent,
            &grass_position,
            &player_origin
        ));
        assert!(!super::monster_in_attack_range(
            agent,
            &grass_position,
            &Point {
                x: grass_position.x - 1,
                y: grass_position.y + 2,
            }
        ));
        let mut agent = entry.get_mut::<MonsterAgent>().expect("turtle grass agent");
        agent.can_wander = true;
        agent.tracking_player = false;
        agent.attack_interval_ticks = 1;
        agent.next_attack_tick = current_tick;
        agent.next_move_tick = current_tick;
    }
    sync_visible_objects(&mut session);

    let mut saw_show = false;
    let mut saw_attack = false;
    let mut saw_struck = false;
    for _ in 0..8 {
        let packets = session.tick();
        saw_show |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectShow { object_id } if *object_id == grass_object_id
            )
        });
        saw_attack |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectAttack { info } if info.object_id == grass_object_id
            )
        });
        saw_struck |= packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::Struck { info } if info.attacker_id == grass_object_id
            )
        });
        assert!(!packets.iter().any(|packet| {
            matches!(
                packet,
                ServerPacket::ObjectWalk { movement }
                    if movement.object_id == grass_object_id
            )
        }));
        if saw_show && saw_attack && saw_struck {
            break;
        }
    }

    assert!(saw_show);
    assert!(saw_attack);
    assert!(saw_struck);
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "TurtleGrass should use imported Crystal DC damage instead of generic damage"
    );
}

#[test]
fn turtle_grass_type_one_branch_pushes_player_before_delayed_damage() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let player_origin = (320..380)
        .flat_map(|x| (278..312).map(move |y| Point { x, y }))
        .find(|point| {
            let grass_position = Point {
                x: point.x + 1,
                y: point.y,
            };
            can_occupy(session.app.world(), point.clone(), Some(player))
                && can_occupy(session.app.world(), grass_position, None)
                && (1..=3).all(|amount| {
                    can_occupy(
                        session.app.world(),
                        Point {
                            x: point.x - amount,
                            y: point.y,
                        },
                        Some(player),
                    )
                })
        })
        .expect("test should find an open TurtleGrass push lane");
    let grass_position = Point {
        x: player_origin.x + 1,
        y: player_origin.y,
    };
    let grass_object_id = 98_955_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let grass = spawn_crystal_monster_for_test(
        &mut session,
        grass_object_id,
        "TurtleGrass",
        grass_position,
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    let branch_tick = current_tick + (4 - current_tick % 4);
    {
        let mut entry = session.app.world_mut().entity_mut(grass);
        {
            let mut ai_state = entry
                .get_mut::<MonsterAiState>()
                .expect("turtle grass ai state");
            ai_state.extra = false;
        }
        let mut agent = entry.get_mut::<MonsterAgent>().expect("turtle grass agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = branch_tick;
        agent.next_move_tick = branch_tick;
    }
    sync_visible_objects(&mut session);

    let mut branch_packets = Vec::new();
    while runtime_tick(session.app.world()) < branch_tick {
        branch_packets = session.tick();
    }
    assert!(branch_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::ObjectAttack { info }
                if info.object_id == grass_object_id
                    && info.attack_type == 1
                    && info.direction == MirDirection::Left
        )
    }));
    assert_eq!(
        branch_packets.iter().find_map(|packet| match packet {
            ServerPacket::ObjectWalk { movement } if movement.object_id == player_object_id => {
                Some(movement.position.clone())
            }
            _ => None,
        }),
        Some(Point {
            x: player_origin.x - 3,
            y: player_origin.y,
        })
    );
    assert!(!branch_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == grass_object_id
        )
    }));

    let damage_packets = session.tick();
    assert!(damage_packets.iter().any(|packet| {
        matches!(
            packet,
            ServerPacket::Struck { info } if info.attacker_id == grass_object_id
        )
    }));
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "TurtleGrass type-1 branch should still apply imported Crystal DC damage"
    );
}

