#[test]
fn red_foxman_type_one_range_branch_uses_imported_dc() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let player_origin = Point { x: 900, y: 900 };
    let fox_object_id = 98_978_u32;
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    set_player_position(&mut session, player_origin.clone());
    let fox = spawn_crystal_monster_for_test(
        &mut session,
        fox_object_id,
        "RedFoxMan",
        Point {
            x: player_origin.x + 6,
            y: player_origin.y,
        },
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    let mut branch_tick = current_tick + 1;
    while branch_tick % 2 != 0 {
        branch_tick += 1;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(fox);
        {
            let mut ai_state = entry
                .get_mut::<MonsterAiState>()
                .expect("red foxman ai state");
            ai_state.next_state_tick = branch_tick + 10;
        }
        let mut agent = entry.get_mut::<MonsterAgent>().expect("red foxman agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = branch_tick;
        agent.next_move_tick = branch_tick;
    }
    sync_visible_objects(&mut session);

    let mut branch_packets = Vec::new();
    while runtime_tick(session.app.world()) < branch_tick {
        branch_packets = session.tick();
    }
    assert!(branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectRangeAttack { info }
            if info.object_id == fox_object_id
                && info.target_id == player_object_id
                && info.attack_type == 1
    )));
    assert!(!branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectAttack { info } if info.object_id == fox_object_id
    )));

    let hit_packets = session.tick();
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == fox_object_id
    )));
    assert!(
        before_hp - session.world_snapshot().player_hp.expect("player hp") > 7,
        "RedFoxMan range branches should use imported Crystal DC damage"
    );
}

