#[test]
fn water_dragon_range_hit_applies_green_poison() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player = player_entity(session.app.world()).expect("player entity");
    let player_object_id = entity_object_id(session.app.world(), player).expect("player object id");
    let player_origin = Point { x: 900, y: 900 };
    let hydra_position = Point {
        x: player_origin.x + 5,
        y: player_origin.y,
    };
    let hydra_object_id = 98_974_u32;
    set_player_position(&mut session, player_origin.clone());
    session
        .app
        .world_mut()
        .entity_mut(player)
        .insert(super::PlayerVitals {
            hp: 500,
            max_hp: 500,
            mp: 100,
            max_mp: 100,
        });
    let before_hp = session.world_snapshot().player_hp.expect("player hp");
    // The water-dragon ranged strike is an armour-ignoring magic hit (the Crystal
    // magic channel is mitigated by MAC, not the physical AC that
    // `total_defence_bonus` returns), so the measured HP loss is the monster's
    // full magic damage. #16's stat engine gave the seed player nonzero physical
    // defence, which the old `- total_defence_bonus` expectation wrongly
    // subtracted. The hit also applies green poison (asserted below), but its
    // first DOT tick lands after this hit resolves, so it is not part of this loss.
    let expected_damage = super::crystal_monster_magic_damage("Hydra");
    let hydra = spawn_crystal_monster_for_test(
        &mut session,
        hydra_object_id,
        "Hydra",
        hydra_position.clone(),
        MirDirection::Left,
        true,
    );
    let current_tick = runtime_tick(session.app.world());
    let hit_delay = super::ranged_attack_delay_ticks(&hydra_position, &player_origin);
    let mut branch_tick = current_tick + 1;
    while !super::deterministic_chance_roll(
        branch_tick + hit_delay,
        hydra_object_id,
        28,
        super::WATER_DRAGON_GREEN_POISON_CHANCE_DENOMINATOR,
    ) {
        branch_tick += 1;
    }
    {
        let mut entry = session.app.world_mut().entity_mut(hydra);
        let mut agent = entry.get_mut::<MonsterAgent>().expect("hydra agent");
        agent.can_wander = false;
        agent.tracking_player = true;
        agent.attack_interval_ticks = 20;
        agent.next_attack_tick = branch_tick;
        agent.next_move_tick = branch_tick;
    }
    sync_visible_objects(&mut session);

    let mut branch_packets = Vec::new();
    while runtime_tick(session.app.world()) < branch_tick {
        branch_packets = session.tick();
    }
    assert!(branch_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectRangeAttack { info }
            if info.object_id == hydra_object_id && info.target_id == player_object_id
    )));

    let due_tick = branch_tick + hit_delay;
    let mut damage_packets = Vec::new();
    while runtime_tick(session.app.world()) < due_tick {
        damage_packets = session.tick();
    }
    assert!(damage_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Struck { info } if info.attacker_id == hydra_object_id
    )));
    assert_eq!(
        before_hp - session.world_snapshot().player_hp.expect("player hp"),
        expected_damage
    );
    assert!(session
        .world_snapshot()
        .active_buffs
        .iter()
        .any(|buff| buff.key == super::TOXIC_GHOUL_GREEN_POISON_BUFF_KEY));
}

