#[test]
fn world_snapshot_filters_outside_player_aoi() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session.move_to(Point { x: 326, y: 270 });
    let _ = session.interact(4001);
    kill_field_wasp(&mut session);

    set_player_position(&mut session, Point { x: 342, y: 279 });
    let snapshot = session.world_snapshot();

    assert_eq!(
        snapshot.scene_view.as_ref().map(|view| view.center.x),
        Some(342)
    );
    assert_eq!(
        snapshot.scene_view.as_ref().map(|view| view.center.y),
        Some(279)
    );
    assert!(!snapshot
        .entities
        .iter()
        .any(|entity| entity.object_id == 2001));
    assert!(!snapshot
        .entities
        .iter()
        .any(|entity| entity.object_id == 3002));
    assert!(!snapshot
        .entities
        .iter()
        .any(|entity| entity.object_id == 4001));
    assert!(snapshot
        .entities
        .iter()
        .any(|entity| entity.object_id == 3001));
    assert!(snapshot.ground_drops.is_empty());
    assert!(!snapshot
        .decor_objects
        .iter()
        .any(|decor| decor.id == "west-banner"));
    assert!(snapshot.terrain_patches.len() < 6);
}

#[test]
fn attack_reduces_monster_hp() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_player_position(&mut session, Point { x: 333, y: 267 });
    let before = session
        .world_snapshot()
        .entities
        .into_iter()
        .find(|entity| entity.object_id == 3002)
        .and_then(|entity| entity.hp)
        .expect("monster hp");

    let _ = session.attack(3002);
    let _ = session.tick();
    let after = session
        .world_snapshot()
        .entities
        .into_iter()
        .find(|entity| entity.object_id == 3002)
        .and_then(|entity| entity.hp)
        .expect("monster hp");

    assert!(after < before);
}

#[test]
fn defeating_visible_monster_emits_death_packets() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session.move_to(Point { x: 333, y: 267 });

    let packets = attack_until_monster_dies(&mut session, 3002, 5);

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectDied { info } if info.object_id == 3002
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectHealth { info }
            if info.object_id == 3002 && info.percent == 0
    )));
}

#[test]
fn dead_monster_does_not_block_attack_or_die_twice() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session.move_to(Point { x: 333, y: 267 });
    let monster = entity_by_object_id(session.app.world(), 3002).expect("monster entity");
    let monster_position = entity_position(session.app.world(), monster).expect("monster position");

    let death_packets = attack_until_monster_dies(&mut session, 3002, 5);
    assert!(packet_has_object_died(&death_packets, 3002));
    let entry = session.app.world().entity(monster);
    assert!(entry.get::<MonsterAgent>().expect("monster agent").dead);
    assert_eq!(entry.get::<MonsterVitals>().expect("monster vitals").hp, 0);
    assert!(
        can_occupy(session.app.world(), monster_position, None),
        "dead monsters should release occupancy"
    );

    let repeat_packets = session.attack(3002);
    assert!(!packet_has_object_died(&repeat_packets, 3002));
    assert!(!packet_has_object_health(&repeat_packets, 3002));
}

