#[test]
fn crystal_npc_unknown_action_records_script_diagnostic() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let mut packets = Vec::new();
    let mut execution_state = CrystalNpcExecutionState {
        script_key: Some("Test/UnknownAction".to_string()),
        section_label: Some("@Main".to_string()),
        line_number: 42,
        ..CrystalNpcExecutionState::default()
    };

    assert_eq!(
        execute_crystal_npc_action_line(
            session.app.world_mut(),
            "MYSTERYCOMMAND 1 2 3",
            &mut packets,
            &mut execution_state,
        ),
        CrystalNpcActionControl::Continue
    );

    let diagnostics = &session
        .app
        .world()
        .resource::<NpcStateResource>()
        .npc_script_diagnostics;
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic.script_key == "Test/UnknownAction"
            && diagnostic.label == "@Main"
            && diagnostic.line_number == 42
            && diagnostic.command == "MYSTERYCOMMAND"
            && diagnostic.message.contains("Unknown")
    }));
}

