#[test]
fn crystal_npc_check_and_set_flag_drive_followup_dialog_branch() {
    let mut config = SimulationConfig::default();
    config.visible_npcs.push(crate::VisibleNpcRecord {
        object_id: 4990,
        name: "Flag Keeper".to_string(),
        image: 5,
        colour_argb: -1,
        position: Point { x: 331, y: 270 },
        direction: MirDirection::Left,
        quest_ids: Vec::new(),
        script_key: Some("BichonProvince/BichonWall/Board".to_string()),
    });
    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut resources = session.app.world_mut().resource_mut::<SessionResource>();
        resources
            .selected_character
            .as_mut()
            .expect("character should be active")
            .level = 60;
    }

    let _ = session.interact(4990);
    let _ = session.select_npc_dialog_target("@RebirthMain");
    let first_packets = session.select_npc_dialog_target("@RB1");
    let first_snapshot = session.world_snapshot();
    let first_dialog = first_snapshot
        .active_npc_dialog
        .as_ref()
        .expect("rebirth dialog should be active");

    assert!(first_packets.iter().all(|packet| !matches!(
        packet,
        ServerPacket::MapInformation { .. } | ServerPacket::UserLocation { .. }
    )));
    assert!(first_dialog
        .body
        .iter()
        .any(|line| line.contains("Would you like to rebirth")));

    let apply_packets = session.select_npc_dialog_target("@RB1APPLY");
    let apply_snapshot = session.world_snapshot();
    let apply_dialog = apply_snapshot
        .active_npc_dialog
        .as_ref()
        .expect("apply dialog should be active");
    assert!(apply_packets.iter().all(|packet| !matches!(
        packet,
        ServerPacket::MapInformation { .. } | ServerPacket::UserLocation { .. }
    )));
    assert!(apply_dialog
        .body
        .iter()
        .any(|line| line.contains("You are now Reborn.")));

    let _ = session.interact(4990);
    let _ = session.select_npc_dialog_target("@RebirthMain");
    let second_packets = session.select_npc_dialog_target("@RB1");
    let second_snapshot = session.world_snapshot();
    let second_dialog = second_snapshot
        .active_npc_dialog
        .as_ref()
        .expect("rebirth repeat dialog should be active");

    assert!(second_packets.iter().all(|packet| !matches!(
        packet,
        ServerPacket::MapInformation { .. } | ServerPacket::UserLocation { .. }
    )));
    assert!(second_dialog
        .body
        .iter()
        .any(|line| line.contains("already Rebirth 1.")));
}

#[test]
fn crystal_npc_givegold_checkclass_and_gender_execute_expected_branch() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut resources = session.app.world_mut().resource_mut::<SessionResource>();
        let character = resources
            .selected_character
            .as_mut()
            .expect("character should be active");
        character.class = MirClass::Wizard;
        character.gender = MirGender::Female;
    }
    let before_gold = session.world_snapshot().gold;
    let mut packets = Vec::new();

    assert!(evaluate_crystal_npc_condition(
        session.app.world_mut(),
        "CHECKCLASS Wizard"
    ));
    assert!(!evaluate_crystal_npc_condition(
        session.app.world_mut(),
        "CHECKCLASS Warrior"
    ));
    assert!(evaluate_crystal_npc_condition(
        session.app.world_mut(),
        "GENDER Female"
    ));
    assert!(!evaluate_crystal_npc_condition(
        session.app.world_mut(),
        "CHECKGENDER Male"
    ));
    assert_eq!(
        execute_crystal_npc_action_line(
            session.app.world_mut(),
            "GIVEGOLD 1000",
            &mut packets,
            &mut CrystalNpcExecutionState::default(),
        ),
        CrystalNpcActionControl::Continue
    );
    assert!(packets.is_empty());
    assert_eq!(session.world_snapshot().gold, before_gold + 1_000);
}

