#[test]
fn crystal_npc_mov_and_checkcalc_drive_lottery_guess_flow() {
    let mut config = SimulationConfig::default();
    config.visible_npcs.push(crate::VisibleNpcRecord {
        object_id: 4989,
        name: "Lottery Host".to_string(),
        image: 5,
        colour_argb: -1,
        position: Point { x: 331, y: 270 },
        direction: MirDirection::Left,
        quest_ids: Vec::new(),
        script_key: Some("BichonProvince/BichonWall/Lottery".to_string()),
    });
    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let _ = session.interact(4989);
    {
        session
            .app
            .world_mut()
            .resource_mut::<PlayerRuntimeResource>()
            .gold = 20_000;
        let mut resources = session.app.world_mut().resource_mut::<NpcStateResource>();
        resources
            .npc_variables
            .push(("B3".to_string(), "1".to_string()));
    }

    let _ = session.select_npc_dialog_target("@Play");
    let snapshot = session.world_snapshot();
    let dialog = snapshot
        .active_npc_dialog
        .as_ref()
        .expect("lottery guess dialog should be active");
    assert!(dialog
        .links
        .iter()
        .any(|link| link.target.eq_ignore_ascii_case("@Guess(1)")));

    let _ = session.select_npc_dialog_target("@Guess(1)");
    let win_snapshot = session.world_snapshot();
    let win_dialog = win_snapshot
        .active_npc_dialog
        .as_ref()
        .expect("lottery win dialog should be active");

    assert!(win_dialog
        .body
        .iter()
        .any(|line| line.contains("Congratulations, you Won!")));
}

