#[test]
fn crystal_npc_runtime_token_resolution_replaces_embedded_variables_and_output_placeholders() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut resources = session.app.world_mut().resource_mut::<NpcStateResource>();
        resources
            .npc_variables
            .push(("A1".to_string(), "42".to_string()));
        resources
            .npc_variables
            .push(("B2".to_string(), "Lucky".to_string()));
    }

    let resolved = super::resolve_crystal_npc_runtime_tokens(
        session.app.world(),
        "Value=%A1, text<$OUTPUT(B2)>/%ARG(0)",
        &CrystalNpcExecutionState {
            label_args: vec!["Go".to_string()],
            ..CrystalNpcExecutionState::default()
        },
    );

    assert_eq!(resolved, "Value=42, textLucky/Go");
}

#[test]
fn crystal_npc_input_label_waits_for_input_and_replaces_inputstr_on_submit() {
    let mut config = SimulationConfig::default();
    config.visible_npcs.push(crate::VisibleNpcRecord {
        object_id: 4991,
        name: "Guild Steward".to_string(),
        image: 5,
        colour_argb: -1,
        position: Point { x: 331, y: 270 },
        direction: MirDirection::Left,
        quest_ids: Vec::new(),
        script_key: Some("GuildTerritory/GA0/GTAdmin-GA10".to_string()),
    });
    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let _ = session.interact(4991);
    let _ = session.select_npc_dialog_target("@summon");
    let _ = session.select_npc_dialog_target("@agitonerecall");
    let link_snapshot = session.world_snapshot();
    let link_dialog = link_snapshot
        .active_npc_dialog
        .as_ref()
        .expect("input link dialog should be active");
    assert!(link_dialog
        .links
        .iter()
        .any(|link| link.target.eq_ignore_ascii_case("@@summontest")));

    let _ = session.select_npc_dialog_target("@@summontest");
    let wait_snapshot = session.world_snapshot();
    let wait_dialog = wait_snapshot
        .active_npc_dialog
        .as_ref()
        .expect("input dialog should be active");
    assert_eq!(
        wait_dialog
            .input
            .as_ref()
            .map(|input| input.target.as_str()),
        Some("@@summontest")
    );
    assert!(wait_dialog
        .input
        .as_ref()
        .is_some_and(|input| input.prompt.contains("Who do you wish to summon")));

    let _ = session.submit_npc_input("Scout");

    assert_eq!(
        super::crystal_npc_variable_value(session.app.world(), "A1").as_deref(),
        Some("Scout")
    );
    assert!(session.world_snapshot().active_npc_dialog.is_none());
}

