#[test]
fn crystal_drop_table_gold_entry_spawns_pickup_gold_for_monster_death() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let monster_position = Point { x: 342, y: 270 };
    let monster_object_id = 98_917_u32;
    let monster = spawn_crystal_monster_for_test(
        &mut session,
        monster_object_id,
        "OmaFighter",
        monster_position.clone(),
        MirDirection::Left,
        true,
    );

    let current_tick = runtime_tick(session.app.world());
    let mut packets = Vec::new();
    assert!(super::damage_monster_entity(
        session.app.world_mut(),
        monster,
        i32::MAX,
        current_tick,
        &mut packets,
    ));
    super::handle_monster_defeat(
        session.app.world_mut(),
        monster_object_id,
        "OmaFighter",
        &mut packets,
    );
    assert!(!packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));

    let expected_gold = super::crystal_drop_gold_amount(2000, current_tick, monster_object_id, 0);
    let expected_chunks = super::crystal_ground_gold_chunks(expected_gold);
    let drops = session
        .world_snapshot()
        .ground_drops
        .into_iter()
        .filter(|drop| drop.name == "Gold" && drop.quantity == 1)
        .collect::<Vec<_>>();
    assert_eq!(
        drops.len(),
        expected_chunks.len(),
        "OmaFighter should spawn Crystal MaxDropGold chunks"
    );

    assert!((1000..3000).contains(&expected_gold));
    let mut picked_gold = Vec::new();
    for drop in drops {
        set_player_position(
            &mut session,
            Point {
                x: drop.x,
                y: drop.y,
            },
        );
        let pickup_packets = session.pick_up(drop.object_id);
        picked_gold.extend(
            pickup_packets
                .into_iter()
                .filter_map(|packet| match packet {
                    ServerPacket::GainedGold { gold } => Some(gold),
                    _ => None,
                }),
        );
    }
    assert_eq!(picked_gold, expected_chunks);
    assert_eq!(picked_gold.into_iter().sum::<u32>(), expected_gold);
}

