#[test]
fn sell_item_packet_removes_item_and_adds_gold_without_duplication() {
    let mut session = SimulationSession::new(wicked_trader_config());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let _ = session.interact(4990);
    let _ = session.select_npc_dialog_target("@BuySell");
    let (slot, key, value, gold_before, quantity_before) = {
        let resources = session.app.world().resource::<InventoryResource>();
        let item = resources
            .inventory_items
            .iter()
            .find(|item| {
                item.key == "bronze-helmet"
                    && matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2)
            })
            .expect("sellable bag item should exist");
        (
            item.slot,
            item.key.clone(),
            super::crystal_sell_value_for_item(&ItemState {
                quantity: 1,
                ..item.clone()
            }),
            player_gold(&session),
            item.quantity,
        )
    };

    let packets = session.handle_packet(ClientPacket::SellItem {
        unique_id: u64::from(slot),
        count: 1,
    });

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::SellItem {
            unique_id,
            count: 1,
            success: true
        } if *unique_id == u64::from(slot)
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GainedGold { gold } if *gold == value
    )));
    assert!(packets
        .iter()
        .all(|packet| !matches!(packet, ServerPacket::Chat { .. })));
    let resources = session.app.world().resource::<InventoryResource>();
    assert_eq!(player_gold(&session), gold_before + value);
    if quantity_before == 1 {
        assert!(!resources
            .inventory_items
            .iter()
            .any(|item| item.key == key && item.slot == slot));
    } else {
        assert!(resources.inventory_items.iter().any(|item| item.key == key
            && item.slot == slot
            && item.quantity == quantity_before - 1));
    }
}

#[test]
fn sell_item_packet_uses_unique_id_when_it_differs_from_slot() {
    let mut session = SimulationSession::new(wicked_trader_config());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let _ = session.interact(4990);
    let _ = session.select_npc_dialog_target("@BuySell");
    let (sell_unique_id, expected_gold) = {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let item = resources
            .inventory_items
            .iter_mut()
            .find(|item| item.key == "bronze-helmet")
            .expect("bronze helmet should exist");
        item.unique_id = 9_003;
        let expected_gold = super::crystal_sell_value_for_item(&ItemState {
            quantity: 1,
            ..item.clone()
        });
        (item.unique_id, expected_gold)
    };
    let gold_before = player_gold(&session);

    let packets = session.handle_packet(ClientPacket::SellItem {
        unique_id: sell_unique_id,
        count: 1,
    });
    let resources = session.app.world().resource::<InventoryResource>();

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::SellItem {
            unique_id: 9_003,
            count: 1,
            success: true
        }
    )));
    assert!(packets.iter().any(
        |packet| matches!(packet, ServerPacket::GainedGold { gold } if *gold == expected_gold)
    ));
    assert_eq!(player_gold(&session), gold_before + expected_gold);
    assert!(!resources
        .inventory_items
        .iter()
        .any(|item| item.unique_id == sell_unique_id));
}

#[test]
fn sell_item_invalid_slot_preserves_inventory_and_gold() {
    let mut session = SimulationSession::new(wicked_trader_config());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let _ = session.interact(4990);
    let _ = session.select_npc_dialog_target("@BuySell");
    let (gold_before, items_before) = {
        let resources = session.app.world().resource::<InventoryResource>();
        (
            player_gold(&session),
            resources
                .inventory_items
                .iter()
                .map(|item| {
                    (
                        item.key.clone(),
                        item.slot,
                        item.container,
                        item.quantity,
                        item.durability_current,
                        item.durability_max,
                    )
                })
                .collect::<Vec<_>>(),
        )
    };

    let packets = session.handle_packet(ClientPacket::SellItem {
        unique_id: 250,
        count: 1,
    });

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::SellItem {
            unique_id: 250,
            count: 1,
            success: false
        }
    )));
    assert!(packets
        .iter()
        .all(|packet| !matches!(packet, ServerPacket::Chat { .. })));
    let resources = session.app.world().resource::<InventoryResource>();
    assert_eq!(player_gold(&session), gold_before);
    let items_after = resources
        .inventory_items
        .iter()
        .map(|item| {
            (
                item.key.clone(),
                item.slot,
                item.container,
                item.quantity,
                item.durability_current,
                item.durability_max,
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(items_after, items_before);
}

