#[test]
fn sell_item_partial_stack_rejects_when_gold_cap_would_overflow() {
    let mut session = SimulationSession::new(wicked_trader_config());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        session
            .app
            .world_mut()
            .resource_mut::<PlayerRuntimeResource>()
            .gold = u32::MAX;
        let mut resources = session.app.world_mut().resource_mut::<NpcStateResource>();
        resources.active_npc_service = Some(super::ActiveNpcServiceState {
            script_key: "00Default".to_string(),
            label_key: "SELL".to_string(),
            npc_object_id: 0,
        });
    }
    let quantity_before = session
        .app
        .world()
        .resource::<InventoryResource>()
        .inventory_items
        .iter()
        .find(|item| item.slot == 0 && item.container == ItemContainer::Bag1)
        .map(|item| item.quantity)
        .expect("starter bag slot should exist");

    let packets = session.handle_packet(ClientPacket::SellItem {
        unique_id: 0,
        count: 1,
    });
    let resources = session.app.world().resource::<InventoryResource>();

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::SellItem {
            unique_id: 0,
            count: 1,
            success: false
        }
    )));
    assert!(packets
        .iter()
        .all(|packet| !matches!(packet, ServerPacket::GainedGold { .. })));
    assert_eq!(player_gold(&session), u32::MAX);
    assert_eq!(
        resources
            .inventory_items
            .iter()
            .find(|item| item.slot == 0 && item.container == ItemContainer::Bag1)
            .map(|item| item.quantity),
        Some(quantity_before)
    );
}

