#[test]
fn benediction_oil_refreshes_weapon_after_luck_gain() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    add_benediction_oil(&mut session, 12);

    let packets = session.use_item("benediction-oil");
    let snapshot = session.world_snapshot();

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::RefreshItem { item }
            if item.item_index == 221
                && item
                    .added_stats
                    .iter()
                    .any(|stat| stat.stat == 15 && stat.value == 1)
    )));
    assert!(snapshot.equipment_items.iter().any(|item| {
        item.slot == EquipmentSlot::Weapon && item.name == "Wooden Sword" && item.added_luck == 1
    }));
    assert!(!snapshot
        .inventory_items
        .iter()
        .any(|item| item.key == "benediction-oil"));
}

#[test]
fn benediction_oil_can_have_no_effect_but_is_consumed() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    add_benediction_oil(&mut session, 12);
    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let weapon = resources
            .equipment_items
            .iter_mut()
            .find(|item| item.slot == EquipmentSlot::Weapon)
            .expect("weapon");
        weapon.added_luck = 1;
    }
    super::set_runtime_tick(session.app.world_mut(), 0);

    let packets = session.use_item("benediction-oil");
    let snapshot = session.world_snapshot();
    let expected_message = super::localized_text_or_fallback(
        super::current_language(session.app.world()),
        "server.WeaponNoEffect",
        "server.WeaponNoEffect",
    );

    assert!(!packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::RefreshItem { .. })));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, chat_type }
            if message == &expected_message && *chat_type == ChatType::Hint
    )));
    assert!(snapshot
        .equipment_items
        .iter()
        .any(|item| { item.slot == EquipmentSlot::Weapon && item.added_luck == 1 }));
    assert!(!snapshot
        .inventory_items
        .iter()
        .any(|item| item.key == "benediction-oil"));
}

