#[test]
fn repair_and_war_god_oil_emit_item_repaired_for_weapon() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let weapon = resources
            .equipment_items
            .iter_mut()
            .find(|item| item.slot == EquipmentSlot::Weapon)
            .expect("starter weapon");
        weapon.durability_current = 10;
        weapon.durability_max = 20;
    }
    add_weapon_oil(&mut session, "repair-oil", "Repair Oil", 12);

    let repair_packets = session.use_item("repair-oil");
    let after_repair = session.world_snapshot();

    assert!(repair_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ItemRepaired {
            unique_id: 0,
            max_dura: 20,
            current_dura: 15,
        }
    )));
    assert!(repair_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, chat_type }
            if message
                == &super::localized_text_or_fallback(
                    super::LanguageCode::English,
                    "server.WeaponPartiallyRepaired",
                    "server.WeaponPartiallyRepaired",
                )
                && *chat_type == ChatType::Hint
    )));
    assert!(!repair_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, chat_type }
            if message == "Your weapon has been repaired." && *chat_type == ChatType::System
    )));
    assert!(after_repair
        .inventory_items
        .iter()
        .all(|item| item.key != "repair-oil"));

    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let weapon = resources
            .equipment_items
            .iter_mut()
            .find(|item| item.slot == EquipmentSlot::Weapon)
            .expect("starter weapon");
        weapon.durability_current = 5;
        weapon.durability_max = 20;
    }
    add_weapon_oil(&mut session, "war-god-oil", "War God Oil", 13);

    let war_god_packets = session.use_item("war-god-oil");
    let after_war_god = session.world_snapshot();

    assert!(war_god_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ItemRepaired {
            unique_id: 0,
            max_dura: 20,
            current_dura: 20,
        }
    )));
    assert!(war_god_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, chat_type }
            if message
                == &super::localized_text_or_fallback(
                    super::LanguageCode::English,
                    "server.WeaponCompletelyRepaired",
                    "server.WeaponCompletelyRepaired",
                )
                && *chat_type == ChatType::Hint
    )));
    assert!(!war_god_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, chat_type }
            if message == "Your weapon has been repaired." && *chat_type == ChatType::System
    )));
    assert!(after_war_god
        .inventory_items
        .iter()
        .all(|item| item.key != "war-god-oil"));
}

