#[test]
fn item_roll_fields_persist_through_save_and_reload() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    register_test_account(&session, "roll-save");
    let packets = session.handle_packet(ClientPacket::Login {
        account_id: "demo".to_string(),
        password: "demo".to_string(),
    });
    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoginSuccess { .. })));
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_active_character_class_gender_level(&mut session, MirClass::Warrior, MirGender::Male, 10);
    let _ = session.use_item("bronze-helmet");
    add_inventory_crystal_item(&mut session, "MysteryHelmet", 31);

    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let weapon = resources
            .equipment_items
            .iter_mut()
            .find(|item| item.slot == EquipmentSlot::Weapon)
            .expect("weapon");
        weapon.grade = ItemGrade::Rare;
        weapon.added_attack = 5;
        weapon.added_stats.push(super::UserItemStat {
            stat: super::CRYSTAL_STAT_MAX_MC,
            value: 4,
        });
        weapon.cursed = true;
        weapon.socket_slots = 2;

        let potion = resources
            .inventory_items
            .iter_mut()
            .find(|item| item.key == "red-potion")
            .expect("seed potion");
        potion.added_stats.push(super::UserItemStat {
            stat: super::CRYSTAL_STAT_ACCURACY,
            value: 2,
        });
        potion.cursed = true;
        potion.socket_slots = 1;

        let mystery_helmet = resources
            .inventory_items
            .iter_mut()
            .find(|item| item.slot == 31)
            .expect("mystery helmet");
        mystery_helmet.identified = Some(true);
        mystery_helmet.soul_bound_id = Some(77);
    }

    session.save_active_character();

    let mut reloaded_config = SimulationConfig::default();
    reloaded_config.account_store = session
        .app
        .world()
        .resource::<RuntimeConfigResource>()
        .config
        .account_store
        .clone();
    let mut reloaded = SimulationSession::new(reloaded_config);
    let login_packets = reloaded.handle_packet(ClientPacket::Login {
        account_id: "demo".to_string(),
        password: "demo".to_string(),
    });
    assert!(login_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoginSuccess { .. })));
    reloaded.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let snapshot = reloaded.world_snapshot();
    assert_eq!(
        snapshot
            .equipment_items
            .iter()
            .find(|item| item.slot == EquipmentSlot::Weapon)
            .map(|item| (item.grade, item.added_attack, item.attack)),
        Some((ItemGrade::Rare, 5, 9))
    );
    assert_eq!(
        snapshot
            .equipment_items
            .iter()
            .find(|item| item.slot == EquipmentSlot::Helmet)
            .map(|item| (item.grade, item.added_defence, item.defence)),
        Some((ItemGrade::Common, 1, 3))
    );
    let resources = reloaded.app.world().resource::<InventoryResource>();
    let weapon = resources
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("reloaded weapon");
    assert!(weapon.cursed);
    assert_eq!(weapon.socket_slots, 2);
    assert!(weapon
        .added_stats
        .iter()
        .any(|stat| { stat.stat == super::CRYSTAL_STAT_MAX_MC && stat.value == 4 }));

    let potion = resources
        .inventory_items
        .iter()
        .find(|item| item.key == "red-potion")
        .expect("reloaded potion");
    assert!(potion.cursed);
    assert_eq!(potion.socket_slots, 1);
    assert!(potion
        .added_stats
        .iter()
        .any(|stat| { stat.stat == super::CRYSTAL_STAT_ACCURACY && stat.value == 2 }));
    let mystery_helmet = resources
        .inventory_items
        .iter()
        .find(|item| item.slot == 31)
        .expect("reloaded mystery helmet");
    assert_eq!(mystery_helmet.identified, Some(true));
    assert_eq!(mystery_helmet.soul_bound_id, Some(77));
}

#[test]
fn storing_item_moves_bag_item_into_storage_snapshot() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);

    let bag_item = session
        .world_snapshot()
        .inventory_items
        .into_iter()
        .find(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
        .expect("bag item");

    let packets = session.handle_packet(ClientPacket::StoreItem {
        from: i32::from(bag_item.slot),
        to: 4,
    });
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::StoreItem {
            from,
            to: 4,
            success: true
        } if *from == i32::from(bag_item.slot)
    )));
    assert!(packets
        .iter()
        .all(|packet| !matches!(packet, ServerPacket::Chat { .. })));

    let snapshot = session.world_snapshot();
    assert!(!snapshot
        .inventory_items
        .iter()
        .any(|item| item.key == bag_item.key && item.slot == bag_item.slot));
    assert!(snapshot
        .storage_items
        .iter()
        .any(|item| item.key == bag_item.key
            && item.slot == 4
            && item.container == ItemContainer::Storage));
}

#[test]
fn storing_item_uses_crystal_inventory_index_for_bag2_slots() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);

    let packets = session.handle_packet(ClientPacket::StoreItem { from: 40, to: 4 });

    assert_eq!(
        packets,
        vec![ServerPacket::StoreItem {
            from: 40,
            to: 4,
            success: true,
        }]
    );
    let snapshot = session.world_snapshot();
    assert!(!snapshot.inventory_items.iter().any(|item| {
        item.key == "town-teleport" && item.container == ItemContainer::Bag2 && item.slot == 0
    }));
    assert!(snapshot.storage_items.iter().any(|item| {
        item.key == "town-teleport" && item.container == ItemContainer::Storage && item.slot == 4
    }));
}

#[test]
fn taking_back_item_moves_storage_item_into_inventory_snapshot() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);

    let stored_item = session
        .world_snapshot()
        .storage_items
        .into_iter()
        .find(|item| item.slot == 0)
        .expect("stored item");

    let packets = session.handle_packet(ClientPacket::TakeBackItem { from: 0, to: 6 });
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::TakeBackItem {
            from: 0,
            to: 6,
            success: true
        }
    )));
    assert!(packets
        .iter()
        .all(|packet| !matches!(packet, ServerPacket::Chat { .. })));

    let snapshot = session.world_snapshot();
    assert!(!snapshot
        .storage_items
        .iter()
        .any(|item| item.key == stored_item.key));
    assert!(snapshot
        .inventory_items
        .iter()
        .any(|item| item.key == stored_item.key
            && item.slot == 6
            && item.container == ItemContainer::Bag1));
}

#[test]
fn taking_back_item_rekeys_dirty_duplicate_inventory_unique_id() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);

    let duplicate_unique_id = {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let duplicate_unique_id = resources
            .inventory_items
            .iter()
            .find(|item| item.slot == 2 && item.container == ItemContainer::Bag1)
            .map(|item| item.unique_id)
            .expect("bag item unique id");
        let stored_item = resources
            .storage_items
            .iter_mut()
            .find(|item| item.slot == 0)
            .expect("stored item");
        stored_item.unique_id = duplicate_unique_id;
        duplicate_unique_id
    };

    let packets = session.handle_packet(ClientPacket::TakeBackItem { from: 0, to: 6 });
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::TakeBackItem {
            from: 0,
            to: 6,
            success: true
        }
    )));

    let snapshot = session.world_snapshot();
    let moved_item = snapshot
        .inventory_items
        .iter()
        .find(|item| item.key == "stored-red-potion" && item.slot == 6)
        .expect("taken-back item");
    assert_ne!(moved_item.unique_id, duplicate_unique_id);
    assert_eq!(
        snapshot
            .inventory_items
            .iter()
            .filter(|item| item.unique_id == duplicate_unique_id)
            .count(),
        1
    );
}

#[test]
fn stage5_craft_allocates_unique_id_when_preferred_slot_collides_with_storage() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);

    let store_packets = session.handle_packet(ClientPacket::StoreItem { from: 4, to: 4 });
    assert!(store_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::StoreItem {
            from: 4,
            to: 4,
            success: true
        }
    )));

    session.stage5_command("mine", vec!["1".to_string()]);
    session.stage5_command("craft", vec!["crafted-blade".to_string()]);

    let snapshot = session.world_snapshot();
    let crafted_item = snapshot
        .inventory_items
        .iter()
        .find(|item| item.key == "crafted-blade" && item.slot == 4)
        .expect("crafted item should use the freed slot");
    let stored_dagger = snapshot
        .storage_items
        .iter()
        .find(|item| item.key == "dagger" && item.slot == 4)
        .expect("stored dagger");
    assert_ne!(crafted_item.unique_id, stored_dagger.unique_id);
}

#[test]
fn taking_back_item_uses_crystal_inventory_index_for_bag2_slots() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);
    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        resources
            .inventory_items
            .retain(|item| !(item.container == ItemContainer::Bag2 && item.slot == 0));
    }

    let packets = session.handle_packet(ClientPacket::TakeBackItem { from: 0, to: 40 });

    assert_eq!(
        packets,
        vec![ServerPacket::TakeBackItem {
            from: 0,
            to: 40,
            success: true,
        }]
    );
    let snapshot = session.world_snapshot();
    assert!(!snapshot.storage_items.iter().any(|item| {
        item.key == "stored-red-potion" && item.container == ItemContainer::Storage
    }));
    assert!(snapshot.inventory_items.iter().any(|item| {
        item.key == "stored-red-potion" && item.container == ItemContainer::Bag2 && item.slot == 0
    }));
}

#[test]
fn storage_items_persist_through_save_and_reload() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    register_test_account(&session, "storage-save");
    let packets = session.handle_packet(ClientPacket::Login {
        account_id: "demo".to_string(),
        password: "demo".to_string(),
    });
    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoginSuccess { .. })));
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);

    let moved_key = {
        let snapshot = session.world_snapshot();
        let bag_item = snapshot
            .inventory_items
            .iter()
            .find(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
            .expect("bag item");
        let moved_key = bag_item.key.clone();
        let _ = session.handle_packet(ClientPacket::StoreItem {
            from: i32::from(bag_item.slot),
            to: 5,
        });
        moved_key
    };

    session.save_active_character();

    let mut reloaded_config = SimulationConfig::default();
    reloaded_config.account_store = session
        .app
        .world()
        .resource::<RuntimeConfigResource>()
        .config
        .account_store
        .clone();
    let mut reloaded = SimulationSession::new(reloaded_config);
    let login_packets = reloaded.handle_packet(ClientPacket::Login {
        account_id: "demo".to_string(),
        password: "demo".to_string(),
    });
    assert!(login_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoginSuccess { .. })));
    reloaded.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let snapshot = reloaded.world_snapshot();
    assert!(snapshot
        .storage_items
        .iter()
        .any(|item| item.key == moved_key
            && item.slot == 5
            && item.container == ItemContainer::Storage));
}

#[test]
fn store_and_take_back_reject_occupied_targets_like_crystal() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);

    let snapshot = session.world_snapshot();
    let bag_item = snapshot
        .inventory_items
        .into_iter()
        .find(|item| item.slot == 2 && item.container == ItemContainer::Bag1)
        .expect("bag slot zero item");
    let stored_item = snapshot
        .storage_items
        .into_iter()
        .find(|item| item.slot == 0)
        .expect("storage slot zero item");

    let store_packets = session.handle_packet(ClientPacket::StoreItem { from: 2, to: 0 });
    assert_eq!(
        store_packets,
        vec![ServerPacket::StoreItem {
            from: 2,
            to: 0,
            success: false
        }]
    );
    let after_store = session.world_snapshot();
    assert!(after_store
        .inventory_items
        .iter()
        .any(|item| item.key == bag_item.key
            && item.slot == 2
            && item.container == ItemContainer::Bag1));
    assert!(after_store
        .storage_items
        .iter()
        .any(|item| item.key == stored_item.key
            && item.slot == 0
            && item.container == ItemContainer::Storage));

    let take_back_packets = session.handle_packet(ClientPacket::TakeBackItem { from: 0, to: 2 });
    assert_eq!(
        take_back_packets,
        vec![ServerPacket::TakeBackItem {
            from: 0,
            to: 2,
            success: false
        }]
    );
    let after_take_back = session.world_snapshot();
    assert!(after_take_back
        .inventory_items
        .iter()
        .any(|item| item.key == bag_item.key
            && item.slot == 2
            && item.container == ItemContainer::Bag1));
    assert!(after_take_back
        .storage_items
        .iter()
        .any(|item| item.key == stored_item.key
            && item.slot == 0
            && item.container == ItemContainer::Storage));
}

