#[test]
fn storage_merge_item_stack_caps_at_crystal_stack_size() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);
    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let base = resources
            .storage_items
            .iter()
            .find(|item| item.key == "stored-red-potion")
            .expect("stored red potion")
            .clone();
        resources.storage_items.clear();

        let mut target = base.clone();
        target.slot = 0;
        target.quantity = 18;
        resources.storage_items.push(target);

        let mut source = base;
        source.slot = 2;
        source.quantity = 4;
        resources.storage_items.push(source);
    }

    let packets = session.handle_packet(ClientPacket::MergeItem {
        grid_from: MirGridType::Storage,
        grid_to: MirGridType::Storage,
        id_from: 2,
        id_to: 0,
    });

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::MergeItem {
            grid_from: MirGridType::Storage,
            grid_to: MirGridType::Storage,
            id_from: 2,
            id_to: 0,
            success: true
        }
    )));
    let snapshot = session.world_snapshot();
    assert!(snapshot.storage_items.iter().any(|item| {
        item.key == "stored-red-potion"
            && item.slot == 0
            && item.quantity == 20
            && item.container == ItemContainer::Storage
    }));
    assert!(snapshot.storage_items.iter().any(|item| {
        item.key == "stored-red-potion"
            && item.slot == 2
            && item.quantity == 2
            && item.container == ItemContainer::Storage
    }));
}

