#[test]
fn locked_storage_blocks_store_and_take_back_until_unlock() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    let _ = session.handle_packet(ClientPacket::Login {
        account_id: "storage-lock".to_string(),
        password: "demo".to_string(),
    });
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let snapshot = session.world_snapshot();
    let bag_item = snapshot
        .inventory_items
        .into_iter()
        .find(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
        .expect("bag item");
    let stored_item = snapshot
        .storage_items
        .into_iter()
        .find(|item| item.slot == 0)
        .expect("stored item");

    activate_storage_service(&mut session);
    let _ = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: String::new(),
        new_password: "vault".to_string(),
    });
    session.handle_packet(ClientPacket::LogOut);
    let restart_packets = session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    assert!(restart_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::UserInformation {
            info
        } if info.has_storage_password && info.require_storage_password
    )));

    activate_storage_service(&mut session);
    let blocked_store = session.handle_packet(ClientPacket::StoreItem {
        from: i32::from(bag_item.slot),
        to: 4,
    });
    assert_eq!(
        blocked_store,
        vec![ServerPacket::StoreItem {
            from: i32::from(bag_item.slot),
            to: 4,
            success: false
        }]
    );
    let after_blocked_store = session.world_snapshot();
    assert!(after_blocked_store
        .inventory_items
        .iter()
        .any(|item| item.key == bag_item.key && item.slot == bag_item.slot));

    let blocked_take_back = session.handle_packet(ClientPacket::TakeBackItem {
        from: i32::from(stored_item.slot),
        to: 6,
    });
    assert_eq!(
        blocked_take_back,
        vec![ServerPacket::TakeBackItem {
            from: i32::from(stored_item.slot),
            to: 6,
            success: false
        }]
    );
    let after_blocked_take_back = session.world_snapshot();
    assert!(after_blocked_take_back
        .storage_items
        .iter()
        .any(|item| item.key == stored_item.key && item.slot == stored_item.slot));

    let unlock_packets = session.handle_packet(ClientPacket::UnlockStorage {
        password: "vault".to_string(),
    });
    assert!(unlock_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::StorageUnlockResult {
            result: 0,
            has_password: true
        }
    )));

    let stored_packets = session.handle_packet(ClientPacket::StoreItem {
        from: i32::from(bag_item.slot),
        to: 4,
    });
    assert!(stored_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::StoreItem {
            from,
            to: 4,
            success: true
        } if *from == i32::from(bag_item.slot)
    )));
}

