#[test]
fn storage_password_can_exist_without_forcing_lock_when_config_disabled() {
    let mut config = SimulationConfig::default();
    config.require_storage_password = false;
    let mut session = SimulationSession::new(config);
    let _ = session.handle_packet(ClientPacket::Login {
        account_id: "storage-setting-off".to_string(),
        password: "demo".to_string(),
    });
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    activate_storage_service(&mut session);
    let set_packets = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: String::new(),
        new_password: "vault".to_string(),
    });
    assert!(set_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::StoragePasswordResult {
            result: 4,
            removing: false,
            has_password: true,
            ..
        }
    )));

    session.handle_packet(ClientPacket::LogOut);
    let restart_packets = session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    assert!(restart_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::UserInformation {
            info
        } if info.has_storage_password && !info.require_storage_password
    )));

    let snapshot = session.world_snapshot();
    let bag_item = snapshot
        .inventory_items
        .into_iter()
        .find(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
        .expect("bag item");
    activate_storage_service(&mut session);
    let store_packets = session.handle_packet(ClientPacket::StoreItem {
        from: i32::from(bag_item.slot),
        to: 4,
    });
    assert!(store_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::StoreItem {
            from,
            to: 4,
            success: true
        } if *from == i32::from(bag_item.slot)
    )));
    let after_store = session.world_snapshot();
    assert!(after_store.has_storage_password);
    assert!(!after_store.require_storage_password);
}

#[test]
fn storage_password_set_unlock_remove_updates_crystal_state() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    register_test_account(&session, "storage-password");
    let login_packets = session.handle_packet(ClientPacket::Login {
        account_id: "demo".to_string(),
        password: "demo".to_string(),
    });
    assert!(login_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoginSuccess { .. })));
    let start_packets = session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    assert!(start_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::UserInformation {
            info
        } if !info.has_storage_password && info.require_storage_password
    )));

    activate_storage_service(&mut session);
    let set_packets = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: String::new(),
        new_password: "vault".to_string(),
    });
    let last_set = match set_packets.iter().find_map(|packet| match packet {
        ServerPacket::StoragePasswordResult {
            result,
            removing,
            has_password,
            last_set_binary_datetime,
        } => {
            assert_eq!(*result, 4);
            assert!(!*removing);
            assert!(*has_password);
            Some(*last_set_binary_datetime)
        }
        _ => None,
    }) {
        Some(value) => value,
        None => panic!("storage password result packet"),
    };
    assert_ne!(last_set, 0);
    assert!(last_set < 0);

    session.handle_packet(ClientPacket::LogOut);
    let restart_packets = session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    assert!(restart_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::UserInformation {
            info
        } if info.has_storage_password && info.require_storage_password
    )));
    let restart_snapshot = session.world_snapshot();
    assert!(restart_snapshot.has_storage_password);
    assert!(restart_snapshot.require_storage_password);
    assert_eq!(
        restart_snapshot.storage_password_last_set_binary_datetime,
        last_set
    );

    activate_storage_service(&mut session);
    let wrong_packets = session.handle_packet(ClientPacket::UnlockStorage {
        password: "wrong".to_string(),
    });
    assert!(wrong_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::StorageUnlockResult {
            result: 2,
            has_password: true
        }
    )));

    let unlock_packets = session.handle_packet(ClientPacket::UnlockStorage {
        password: "vault".to_string(),
    });
    assert!(matches!(
        unlock_packets.as_slice(),
        [
            ServerPacket::StorageUnlockResult {
                result: 0,
                has_password: true
            },
            ServerPacket::UserStorage { storage: Some(storage) }
        ] if storage.len() == usize::from(super::BASE_STORAGE_SLOTS)
            && matches!(storage.first(), Some(Some(item)) if item.item_index == 658 && item.count == 10)
    ));
    let unlocked_snapshot = session.world_snapshot();
    assert!(unlocked_snapshot.has_storage_password);
    assert!(!unlocked_snapshot.require_storage_password);
    assert_eq!(
        unlocked_snapshot.storage_password_last_set_binary_datetime,
        last_set
    );

    let remove_packets = session.handle_packet(ClientPacket::RemoveStoragePassword {
        current_password: "vault".to_string(),
    });
    assert!(remove_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::StoragePasswordResult {
            result: 4,
            removing: true,
            has_password: false,
            last_set_binary_datetime: 0,
        }
    )));
    session.handle_packet(ClientPacket::LogOut);
    let final_start_packets = session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    assert!(final_start_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::UserInformation {
            info
        } if !info.has_storage_password && info.require_storage_password
    )));
    let final_snapshot = session.world_snapshot();
    assert_eq!(final_snapshot.storage_password_last_set_binary_datetime, 0);
}

#[test]
fn storage_password_actions_require_active_storage_service_and_data_range() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    let _ = session.handle_packet(ClientPacket::Login {
        account_id: "storage-password-service".to_string(),
        password: "demo".to_string(),
    });
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let blocked_set = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: String::new(),
        new_password: "vault".to_string(),
    });
    assert_eq!(
        blocked_set,
        vec![ServerPacket::StoragePasswordResult {
            result: 0,
            removing: false,
            has_password: false,
            last_set_binary_datetime: 0,
        }]
    );
    let initial_snapshot = session.world_snapshot();
    assert!(!initial_snapshot.has_storage_password);
    assert_eq!(
        initial_snapshot.storage_password_last_set_binary_datetime,
        0
    );

    activate_storage_service(&mut session);
    let set_packets = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: String::new(),
        new_password: "vault".to_string(),
    });
    let last_set = set_packets
        .iter()
        .find_map(|packet| match packet {
            ServerPacket::StoragePasswordResult {
                result: 4,
                removing: false,
                has_password: true,
                last_set_binary_datetime,
            } => Some(*last_set_binary_datetime),
            _ => None,
        })
        .expect("set password should succeed with active storage service");

    session.handle_packet(ClientPacket::LogOut);
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);
    set_player_position(&mut session, Point { x: 348, y: 270 });
    assert!(super::tile_distance(&player_position(&session), &Point { x: 331, y: 270 }) > 16);

    let blocked_update = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: "vault".to_string(),
        new_password: "vault2".to_string(),
    });
    assert!(
        blocked_update.contains(&ServerPacket::StoragePasswordResult {
            result: 0,
            removing: false,
            has_password: true,
            last_set_binary_datetime: last_set,
        })
    );

    let blocked_unlock = session.handle_packet(ClientPacket::UnlockStorage {
        password: "vault".to_string(),
    });
    assert!(blocked_unlock.contains(&ServerPacket::StorageUnlockResult {
        result: 3,
        has_password: true,
    }));

    let blocked_remove = session.handle_packet(ClientPacket::RemoveStoragePassword {
        current_password: "vault".to_string(),
    });
    assert!(
        blocked_remove.contains(&ServerPacket::StoragePasswordResult {
            result: 0,
            removing: true,
            has_password: true,
            last_set_binary_datetime: last_set,
        })
    );

    let locked_snapshot = session.world_snapshot();
    assert!(locked_snapshot.has_storage_password);
    assert!(locked_snapshot.require_storage_password);
    assert_eq!(
        locked_snapshot.storage_password_last_set_binary_datetime,
        last_set
    );

    set_player_position(&mut session, Point { x: 331, y: 270 });
    let unlock_packets = session.handle_packet(ClientPacket::UnlockStorage {
        password: "vault".to_string(),
    });
    assert!(unlock_packets.contains(&ServerPacket::StorageUnlockResult {
        result: 0,
        has_password: true,
    }));
}

#[test]
fn storage_password_set_enforces_crystal_password_format() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    let _ = session.handle_packet(ClientPacket::Login {
        account_id: "storage-password-format-set".to_string(),
        password: "demo".to_string(),
    });
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);

    let short_new_password = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: String::new(),
        new_password: "abcd".to_string(),
    });
    assert_eq!(
        short_new_password,
        vec![ServerPacket::StoragePasswordResult {
            result: 3,
            removing: false,
            has_password: false,
            last_set_binary_datetime: 0,
        }]
    );

    let valid_password = "Vault1234567890".to_string();
    let set_packets = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: String::new(),
        new_password: valid_password.clone(),
    });
    let last_set = set_packets
        .iter()
        .find_map(|packet| match packet {
            ServerPacket::StoragePasswordResult {
                result: 4,
                removing: false,
                has_password: true,
                last_set_binary_datetime,
            } => Some(*last_set_binary_datetime),
            _ => None,
        })
        .expect("valid storage password should be accepted");
    assert_ne!(last_set, 0);

    let invalid_current_password = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: "abc d".to_string(),
        new_password: "Change12345".to_string(),
    });
    assert_eq!(
        invalid_current_password,
        vec![ServerPacket::StoragePasswordResult {
            result: 1,
            removing: false,
            has_password: true,
            last_set_binary_datetime: last_set,
        }]
    );

    let wrong_current_password = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: "Wrong1".to_string(),
        new_password: "Change12345".to_string(),
    });
    assert_eq!(
        wrong_current_password,
        vec![ServerPacket::StoragePasswordResult {
            result: 2,
            removing: false,
            has_password: true,
            last_set_binary_datetime: last_set,
        }]
    );

    let invalid_replacement_password = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: valid_password,
        new_password: "bad!".to_string(),
    });
    assert_eq!(
        invalid_replacement_password,
        vec![ServerPacket::StoragePasswordResult {
            result: 3,
            removing: false,
            has_password: true,
            last_set_binary_datetime: last_set,
        }]
    );
}

#[test]
fn storage_password_unlock_and_remove_enforce_crystal_password_format() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    let _ = session.handle_packet(ClientPacket::Login {
        account_id: "storage-password-format-unlock".to_string(),
        password: "demo".to_string(),
    });
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);

    let password = "Vault123".to_string();
    let set_packets = session.handle_packet(ClientPacket::SetStoragePassword {
        current_password: String::new(),
        new_password: password.clone(),
    });
    let last_set = set_packets
        .iter()
        .find_map(|packet| match packet {
            ServerPacket::StoragePasswordResult {
                result: 4,
                removing: false,
                has_password: true,
                last_set_binary_datetime,
            } => Some(*last_set_binary_datetime),
            _ => None,
        })
        .expect("valid storage password should be accepted");

    session.handle_packet(ClientPacket::LogOut);
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    activate_storage_service(&mut session);

    let invalid_unlock = session.handle_packet(ClientPacket::UnlockStorage {
        password: "abc d".to_string(),
    });
    assert_eq!(
        invalid_unlock,
        vec![ServerPacket::StorageUnlockResult {
            result: 1,
            has_password: true,
        }]
    );

    let wrong_unlock = session.handle_packet(ClientPacket::UnlockStorage {
        password: "Wrong1".to_string(),
    });
    assert_eq!(
        wrong_unlock,
        vec![ServerPacket::StorageUnlockResult {
            result: 2,
            has_password: true,
        }]
    );

    let invalid_remove = session.handle_packet(ClientPacket::RemoveStoragePassword {
        current_password: "abc d".to_string(),
    });
    assert_eq!(
        invalid_remove,
        vec![ServerPacket::StoragePasswordResult {
            result: 1,
            removing: true,
            has_password: true,
            last_set_binary_datetime: last_set,
        }]
    );

    let wrong_remove = session.handle_packet(ClientPacket::RemoveStoragePassword {
        current_password: "Wrong1".to_string(),
    });
    assert_eq!(
        wrong_remove,
        vec![ServerPacket::StoragePasswordResult {
            result: 2,
            removing: true,
            has_password: true,
            last_set_binary_datetime: last_set,
        }]
    );

    let remove_packets = session.handle_packet(ClientPacket::RemoveStoragePassword {
        current_password: password,
    });
    assert_eq!(
        remove_packets,
        vec![ServerPacket::StoragePasswordResult {
            result: 4,
            removing: true,
            has_password: false,
            last_set_binary_datetime: 0,
        }]
    );

    let no_password_remove = session.handle_packet(ClientPacket::RemoveStoragePassword {
        current_password: "Wrong1".to_string(),
    });
    assert_eq!(
        no_password_remove,
        vec![ServerPacket::StoragePasswordResult {
            result: 5,
            removing: true,
            has_password: false,
            last_set_binary_datetime: 0,
        }]
    );
}

#[test]
fn expanded_storage_state_flows_through_user_information_resize_packet_and_snapshot() {
    let config = SimulationConfig::default();
    let expiry = super::future_binary_datetime(30);
    {
        let mut store = config
            .account_store
            .lock()
            .expect("account store mutex should not be poisoned");
        let account = store.accounts.get_mut("demo").expect("demo account");
        account.storage_size = EXPANDED_STORAGE_SLOTS;
        account.has_expanded_storage = true;
        account.expanded_storage_expiry_time_binary_datetime = expiry;
    }

    let mut session = SimulationSession::new(config);
    let packets = session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::UserInformation {
            info
        } if info.has_expanded_storage
            && info.expanded_storage_expiry_time_binary_datetime == expiry
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ResizeStorage {
            size,
            has_expanded_storage,
            expiry_time_binary_datetime
        } if *size == i32::from(EXPANDED_STORAGE_SLOTS)
            && *has_expanded_storage
            && *expiry_time_binary_datetime == expiry
    )));

    let snapshot = session.world_snapshot();
    assert_eq!(snapshot.storage_size, EXPANDED_STORAGE_SLOTS);
    assert!(snapshot.has_expanded_storage);
    assert_eq!(
        snapshot.expanded_storage_expiry_time_binary_datetime,
        expiry
    );
}

#[test]
fn addstorage_chat_command_expands_storage_and_updates_snapshot() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let packets = session.handle_packet(ClientPacket::Chat {
        message: "@ADDSTORAGE".to_string(),
        linked_items: Vec::new(),
    });

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ResizeStorage {
            size,
            has_expanded_storage,
            expiry_time_binary_datetime
        } if *size == i32::from(EXPANDED_STORAGE_SLOTS)
            && *has_expanded_storage
            && *expiry_time_binary_datetime != 0
    )));
    assert!(!packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));

    let snapshot = session.world_snapshot();
    assert_eq!(snapshot.storage_size, EXPANDED_STORAGE_SLOTS);
    assert!(snapshot.has_expanded_storage);
    assert_ne!(snapshot.expanded_storage_expiry_time_binary_datetime, 0);
}

#[test]
fn addstorage_chat_command_extends_existing_expiry() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let first_packets = session.handle_packet(ClientPacket::Chat {
        message: "@ADDSTORAGE".to_string(),
        linked_items: Vec::new(),
    });
    let first_expiry = first_packets
        .iter()
        .find_map(|packet| match packet {
            ServerPacket::ResizeStorage {
                expiry_time_binary_datetime,
                ..
            } => Some(*expiry_time_binary_datetime),
            _ => None,
        })
        .expect("first resize storage packet");

    let second_packets = session.handle_packet(ClientPacket::Chat {
        message: "@ADDSTORAGE".to_string(),
        linked_items: Vec::new(),
    });
    let second_expiry = second_packets
        .iter()
        .find_map(|packet| match packet {
            ServerPacket::ResizeStorage {
                expiry_time_binary_datetime,
                ..
            } => Some(*expiry_time_binary_datetime),
            _ => None,
        })
        .expect("second resize storage packet");

    assert!(second_expiry > first_expiry);
}

#[test]
fn chat_packet_respects_persisted_chat_ban() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut player = session
            .app
            .world_mut()
            .resource_mut::<PlayerRuntimeResource>();
        player.chat_banned = true;
        player.chat_ban_until_ms = Some(u64::MAX);
    }

    let packets = session.handle_packet(ClientPacket::Chat {
        message: "hello".to_string(),
        linked_items: Vec::new(),
    });

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            message,
        } if message.contains("banned from chatting")
    )));
    assert!(!packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ObjectChat { .. })));
}

#[test]
fn expired_chat_ban_clears_and_allows_chat() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut player = session
            .app
            .world_mut()
            .resource_mut::<PlayerRuntimeResource>();
        player.chat_banned = true;
        player.chat_ban_until_ms = Some(1);
    }

    let packets = session.handle_packet(ClientPacket::Chat {
        message: "hello".to_string(),
        linked_items: Vec::new(),
    });

    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ObjectChat { .. })));
    let player = session.app.world().resource::<PlayerRuntimeResource>();
    assert!(!player.chat_banned);
    assert_eq!(player.chat_ban_until_ms, None);
}

#[test]
fn expired_expanded_storage_is_inactive_on_start_game_but_keeps_backing_size() {
    let config = SimulationConfig::default();
    {
        let mut store = config
            .account_store
            .lock()
            .expect("account store mutex should not be poisoned");
        let account = store.accounts.get_mut("demo").expect("demo account");
        account.storage_size = EXPANDED_STORAGE_SLOTS;
        account.has_expanded_storage = true;
        account.expanded_storage_expiry_time_binary_datetime = 1;
    }

    let mut session = SimulationSession::new(config);
    let packets = session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::UserInformation { info }
            if !info.has_expanded_storage
                && info.expanded_storage_expiry_time_binary_datetime == 1
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ResizeStorage {
            size,
            has_expanded_storage,
            expiry_time_binary_datetime
        } if *size == i32::from(EXPANDED_STORAGE_SLOTS)
            && !*has_expanded_storage
            && *expiry_time_binary_datetime == 1
    )));

    let snapshot = session.world_snapshot();
    assert_eq!(snapshot.storage_size, EXPANDED_STORAGE_SLOTS);
    assert!(!snapshot.has_expanded_storage);
    assert_eq!(snapshot.expanded_storage_expiry_time_binary_datetime, 1);
}

#[test]
fn expired_expanded_storage_tick_emits_resize_notice_once_and_persists_flag() {
    let config = SimulationConfig::default();
    {
        let mut store = config
            .account_store
            .lock()
            .expect("account store mutex should not be poisoned");
        let account = store.accounts.get_mut("demo").expect("demo account");
        account.storage_size = EXPANDED_STORAGE_SLOTS;
        account.has_expanded_storage = true;
        account.expanded_storage_expiry_time_binary_datetime = 1;
    }

    let mut session = SimulationSession::new(config.clone());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let first_tick_packets = session.tick();
    assert!(first_tick_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, chat_type }
            if *chat_type == ChatType::System
                && message == &super::localized_text_or_fallback(
                    super::LanguageCode::English,
                    "server.ExpandedStorageExpired",
                    "server.ExpandedStorageExpired",
                )
    )));
    assert!(first_tick_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ResizeStorage {
            size,
            has_expanded_storage,
            expiry_time_binary_datetime
        } if *size == i32::from(EXPANDED_STORAGE_SLOTS)
            && !*has_expanded_storage
            && *expiry_time_binary_datetime == 1
    )));

    let second_tick_packets = session.tick();
    assert!(!second_tick_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. }
            if message == &super::localized_text_or_fallback(
                super::LanguageCode::English,
                "server.ExpandedStorageExpired",
                "server.ExpandedStorageExpired",
            )
    )));
    assert!(!second_tick_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ResizeStorage {
            size,
            has_expanded_storage,
            expiry_time_binary_datetime
        } if *size == i32::from(EXPANDED_STORAGE_SLOTS)
            && !*has_expanded_storage
            && *expiry_time_binary_datetime == 1
    )));

    let store = config
        .account_store
        .lock()
        .expect("account store mutex should not be poisoned");
    let account = store.accounts.get("demo").expect("demo account");
    assert!(!account.has_expanded_storage);
    assert_eq!(account.storage_size, EXPANDED_STORAGE_SLOTS);
    assert_eq!(account.expanded_storage_expiry_time_binary_datetime, 1);
}

#[test]
fn storage_rejects_slots_outside_accessible_capacity() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let bag_item = session
        .world_snapshot()
        .inventory_items
        .into_iter()
        .find(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
        .expect("bag item");

    activate_storage_service(&mut session);
    let invalid_packets = session.handle_packet(ClientPacket::StoreItem {
        from: i32::from(bag_item.slot),
        to: i32::from(BASE_STORAGE_SLOTS),
    });
    assert_eq!(
        invalid_packets,
        vec![ServerPacket::StoreItem {
            from: i32::from(bag_item.slot),
            to: i32::from(BASE_STORAGE_SLOTS),
            success: false
        }]
    );

    let expanded_config = SimulationConfig::default();
    {
        let mut store = expanded_config
            .account_store
            .lock()
            .expect("account store mutex should not be poisoned");
        let account = store.accounts.get_mut("demo").expect("demo account");
        account.storage_size = EXPANDED_STORAGE_SLOTS;
        account.has_expanded_storage = true;
        account.expanded_storage_expiry_time_binary_datetime = super::future_binary_datetime(30);
    }
    let mut expanded_session = SimulationSession::new(expanded_config);
    expanded_session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let expanded_bag_item = expanded_session
        .world_snapshot()
        .inventory_items
        .into_iter()
        .find(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
        .expect("expanded bag item");

    activate_storage_service(&mut expanded_session);
    let valid_packets = expanded_session.handle_packet(ClientPacket::StoreItem {
        from: i32::from(expanded_bag_item.slot),
        to: i32::from(EXPANDED_STORAGE_SLOTS - 1),
    });
    assert!(valid_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::StoreItem {
            from,
            to,
            success: true
        } if *from == i32::from(expanded_bag_item.slot)
            && *to == i32::from(EXPANDED_STORAGE_SLOTS - 1)
    )));
    assert!(expanded_session
        .world_snapshot()
        .storage_items
        .iter()
        .any(|item| {
            item.slot
                == u8::try_from(EXPANDED_STORAGE_SLOTS - 1).expect("expanded slot should fit in u8")
        }));
}

#[test]
fn crystal_npc_storage_open_sends_full_backing_storage_even_when_expansion_inactive() {
    let mut config = SimulationConfig::default();
    config.visible_npcs.push(crate::VisibleNpcRecord {
        object_id: 4991,
        name: "Warehouse Keeper".to_string(),
        image: 5,
        colour_argb: -1,
        position: Point { x: 331, y: 270 },
        direction: MirDirection::Left,
        quest_ids: Vec::new(),
        script_key: Some("BichonProvince/Warehouse-D002".to_string()),
    });
    {
        let mut store = config
            .account_store
            .lock()
            .expect("account store mutex should not be poisoned");
        let account = store.accounts.get_mut("demo").expect("demo account");
        account.storage_size = EXPANDED_STORAGE_SLOTS;
        account.has_expanded_storage = false;
    }

    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let mut high_slot_item = resources
            .storage_items
            .iter()
            .find(|item| item.slot == 0)
            .expect("seed storage item")
            .clone();
        high_slot_item.slot =
            u8::try_from(super::BASE_STORAGE_SLOTS + 20).expect("high slot should fit in u8");
        high_slot_item.unique_id =
            super::default_item_unique_id(ItemContainer::Storage, high_slot_item.slot);
        resources.storage_items.push(high_slot_item);
    }

    let _ = session.interact(4991);
    let storage_packets = session.select_npc_dialog_target("@Storage");
    assert!(matches!(
        storage_packets.as_slice(),
        [ServerPacket::UserStorage { storage: Some(storage) }, ServerPacket::NPCStorage]
            if storage.len() == usize::from(super::EXPANDED_STORAGE_SLOTS)
                && matches!(storage.first(), Some(Some(item)) if item.item_index == 658 && item.count == 10)
                && matches!(
                    storage.get(usize::from(super::BASE_STORAGE_SLOTS + 20)),
                    Some(Some(item)) if item.item_index == 658 && item.count == 10
                )
    ));

    let bag_item = session
        .world_snapshot()
        .inventory_items
        .into_iter()
        .find(|item| matches!(item.container, ItemContainer::Bag1 | ItemContainer::Bag2))
        .expect("bag item");
    let blocked_store = session.handle_packet(ClientPacket::StoreItem {
        from: i32::from(bag_item.slot),
        to: i32::from(BASE_STORAGE_SLOTS),
    });
    assert_eq!(
        blocked_store,
        vec![ServerPacket::StoreItem {
            from: i32::from(bag_item.slot),
            to: i32::from(BASE_STORAGE_SLOTS),
            success: false,
        }]
    );
}

#[test]
fn storage_rejects_rental_dont_store_binding_flags() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        let item = resources
            .inventory_items
            .iter_mut()
            .find(|item| item.slot == 0 && item.container == ItemContainer::Bag1)
            .expect("starter bag item should exist");
        item.rental_binding_flags = super::CRYSTAL_BIND_DONT_STORE;
    }

    activate_storage_service(&mut session);
    let packets = session.handle_packet(ClientPacket::StoreItem { from: 0, to: 7 });

    assert_eq!(
        packets,
        vec![ServerPacket::StoreItem {
            from: 0,
            to: 7,
            success: false
        }]
    );
    let resources = session.app.world().resource::<InventoryResource>();
    assert!(resources.inventory_items.iter().any(|item| {
        item.slot == 0
            && item.container == ItemContainer::Bag1
            && item.rental_binding_flags == super::CRYSTAL_BIND_DONT_STORE
    }));
    assert!(!resources.storage_items.iter().any(|item| item.slot == 7));
}

#[test]
fn equipment_slot_indices_match_crystal() {
    assert_eq!(equipment_slot_from_index(10), Some(EquipmentSlot::Belt));
    assert_eq!(equipment_slot_from_index(11), Some(EquipmentSlot::Boots));
    assert_eq!(equipment_slot_from_index(13), Some(EquipmentSlot::Mount));
    assert_eq!(equipment_slot_index(EquipmentSlot::Belt), Some(10));
    assert_eq!(equipment_slot_index(EquipmentSlot::Boots), Some(11));
    assert_eq!(equipment_slot_index(EquipmentSlot::Mount), Some(13));
}

#[test]
fn player_attack_damages_weapon_durability() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_player_position(&mut session, Point { x: 333, y: 267 });

    let before = session
        .world_snapshot()
        .equipment_items
        .into_iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("weapon before")
        .durability_current;

    let packets = session.attack(3002);
    let after = session
        .world_snapshot()
        .equipment_items
        .into_iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("weapon after")
        .durability_current;

    assert!(after < before);
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::DuraChanged {
            unique_id,
            current_dura
        } if *unique_id == 0 && *current_dura == after
    )));
}

#[test]
fn monster_hit_damages_non_weapon_equipment_durability() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let player_origin = Point { x: 900, y: 900 };
    let monster_object_id = 98_874_u32;
    let current_tick = runtime_tick(session.app.world());
    let before_weapon = session
        .world_snapshot()
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("weapon before")
        .durability_current;
    let before_armour = session
        .world_snapshot()
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Armour)
        .expect("armour before")
        .durability_current;

    set_player_position(&mut session, player_origin.clone());
    let _monster_entity = session
        .app
        .world_mut()
        .spawn((
            ObjectId(monster_object_id),
            DisplayName::literal("Durability Struck Test"),
            Position(Point {
                x: player_origin.x + 1,
                y: player_origin.y,
            }),
            Facing(MirDirection::Left),
            Monster,
            MonsterVitals { hp: 50, max_hp: 50 },
            MonsterAgent {
                image: 43,
                dead: false,
                patrol_origin: player_origin.clone(),
                ai: 0,
                disposition: WorldEntityDisposition::Hostile,
                hostile_to_player: true,
                tracking_player: true,
                view_range: 7,
                can_wander: true,
                move_interval_ticks: 1,
                attack_interval_ticks: 1,
                next_move_tick: current_tick,
                next_attack_tick: current_tick,
                route: Vec::new(),
                route_index: 0,
                route_waiting: false,
                next_route_tick: current_tick,
            },
        ))
        .id();
    sync_visible_objects(&mut session);

    let _launch_packets = session.tick();
    let hit_packets = session.tick();
    let snapshot = session.world_snapshot();
    let after_weapon = snapshot
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("weapon after")
        .durability_current;
    let after_armour = snapshot
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Armour)
        .expect("armour after")
        .durability_current;

    assert_eq!(after_weapon, before_weapon);
    assert!(after_armour < before_armour);
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::DuraChanged {
            unique_id,
            current_dura
        } if *unique_id == 1 && *current_dura == after_armour
    )));
}

#[test]
fn broken_equipment_no_longer_contributes_stats() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut resources = session.app.world_mut().resource_mut::<BuffResource>();
        resources.buffs.clear();
    }
    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        for item in resources.equipment_items.iter_mut() {
            if item.slot == EquipmentSlot::Weapon || item.slot == EquipmentSlot::Armour {
                item.durability_current = 0;
            }
        }
    }
    assert_eq!(total_attack_bonus(session.app.world()), 1);
    assert_eq!(total_defence_bonus(session.app.world()), 2);

    let snapshot = session.world_snapshot();
    assert_eq!(
        snapshot
            .equipment_items
            .iter()
            .find(|item| item.slot == EquipmentSlot::Weapon)
            .expect("weapon")
            .attack,
        0
    );
    assert_eq!(
        snapshot
            .equipment_items
            .iter()
            .find(|item| item.slot == EquipmentSlot::Armour)
            .expect("armour")
            .defence,
        0
    );
}

#[test]
fn repair_powder_restores_equipped_durability_and_consumes_item() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    add_repair_powder(&mut session, 2);
    {
        let mut resources = session.app.world_mut().resource_mut::<InventoryResource>();
        for item in resources.equipment_items.iter_mut() {
            if item.slot == EquipmentSlot::Weapon || item.slot == EquipmentSlot::Armour {
                item.durability_current = 1;
            }
        }
    }

    let packets = session.use_item("repair-powder");
    let snapshot = session.world_snapshot();

    assert!(!packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ItemRepaired {
            unique_id: 0,
            max_dura: 20,
            current_dura: 20
        }
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ItemRepaired {
            unique_id: 1,
            max_dura: 14,
            current_dura: 14
        }
    )));
    assert_eq!(
        snapshot
            .equipment_items
            .iter()
            .find(|item| item.slot == EquipmentSlot::Weapon)
            .map(|item| (item.durability_current, item.durability_max)),
        Some((20, 20))
    );
    assert_eq!(
        snapshot
            .equipment_items
            .iter()
            .find(|item| item.slot == EquipmentSlot::Armour)
            .map(|item| (item.durability_current, item.durability_max)),
        Some((14, 14))
    );
    assert_eq!(
        snapshot
            .inventory_items
            .iter()
            .find(|item| item.key == "repair-powder")
            .map(|item| item.quantity),
        Some(1)
    );
}

