#[test]
fn casting_unwired_skill_rejects_without_runtime_chat_or_cooldown() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session
        .app
        .world_mut()
        .resource_mut::<SkillResource>()
        .skills
        .push(super::SkillState {
            key: "unwired-skill".to_string(),
            name: "Unwired Skill".to_string(),
            description: String::new(),
            level: 1,
            experience: 0,
            hotkey: 0,
            cooldown_ticks: 10,
            delay_ms: 10_000,
            cooldown_ends_at: 0,
            cast_time_ms: 0,
        });

    let packets = session.cast_skill("unwired-skill");
    let snapshot = session.world_snapshot();

    assert!(packets.is_empty());
    assert_eq!(
        snapshot
            .known_skills
            .iter()
            .find(|skill| skill.key == "unwired-skill")
            .map(|skill| skill.cooldown_remaining_ticks),
        Some(0)
    );
}

#[test]
fn casting_skill_requires_mp() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let player = super::player_entity(session.app.world()).expect("player");
        let mut entity = session.app.world_mut().entity_mut(player);
        let mut vitals = entity
            .get_mut::<super::PlayerVitals>()
            .expect("player vitals");
        vitals.mp = 0;
    }

    let packets = session.cast_skill("battle-focus");
    let snapshot = session.world_snapshot();

    assert!(packets.is_empty());
    assert!(!snapshot
        .active_buffs
        .iter()
        .any(|buff| buff.key == "battle-focus"));
    assert_eq!(
        snapshot
            .known_skills
            .iter()
            .find(|skill| skill.key == "battle-focus")
            .map(|skill| skill.cooldown_remaining_ticks)
            .unwrap_or_default(),
        0
    );
}

#[test]
fn magic_packet_casts_crystal_skill_and_emits_magic_packets() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_player_position(&mut session, Point { x: 333, y: 267 });
    let object_id = current_player_object_id(session.app.world()).expect("player object id");

    let packets = session.handle_packet(ClientPacket::Magic {
        object_id,
        spell: Spell::Fury,
        direction: MirDirection::Right,
        target_id: 0,
        location: Point { x: 334, y: 267 },
        spell_target_lock: false,
    });
    let snapshot = session.world_snapshot();

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::UserLocation { location } if location.direction == MirDirection::Right
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Magic {
            spell: Spell::Fury,
            cast: true,
            level: 3,
            ..
        }
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectMagic {
            object_id: packet_object_id,
            direction: MirDirection::Right,
            spell: Spell::Fury,
            cast: true,
            level: 3,
            ..
        } if *packet_object_id == object_id
    )));
    assert!(snapshot
        .active_buffs
        .iter()
        .any(|buff| buff.key == "battle-focus"));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::AddBuff { buff }
            if buff.buff_type == 5
                && buff.visible
                && buff.stats.iter().any(|stat| stat.stat == super::CRYSTAL_STAT_ATTACK_SPEED && stat.value == 4)
    )));
}

