#[test]
fn magic_preflight_healing_self_target_and_action_lock_behave_like_crystal() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_active_character_class_gender_level(&mut session, MirClass::Taoist, MirGender::Female, 25);
    set_current_player_mp(&mut session, 500);
    let player = player_entity(session.app.world()).expect("player entity");
    {
        let current = session
            .app
            .world()
            .entity(player)
            .get::<PlayerVitals>()
            .copied()
            .expect("player vitals");
        session
            .app
            .world_mut()
            .entity_mut(player)
            .insert(PlayerVitals {
                hp: 20,
                max_hp: 120,
                ..current
            });
    }
    let origin = Point { x: 322, y: 277 };
    set_player_position(&mut session, origin.clone());
    {
        let mut skills = session.app.world_mut().resource_mut::<SkillResource>();
        skills
            .skills
            .push(super::crystal_skill_state("Healing", 2).expect("Healing skill"));
        skills
            .skills
            .push(super::crystal_skill_state("MagicShield", 1).expect("MagicShield skill"));
    }
    let object_id = current_player_object_id(session.app.world()).expect("player object id");

    let shield_packets = session.handle_packet(ClientPacket::Magic {
        object_id,
        spell: Spell::MagicShield,
        direction: MirDirection::Right,
        target_id: 0,
        location: origin.clone(),
        spell_target_lock: false,
    });
    let after_shield_mp = session.world_snapshot().player_mp.expect("player mp");
    assert!(shield_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::AddBuff { .. })));
    mark_crystal_packet_action(session.app.world_mut(), PlayerActionKind::Spell, 10);

    let blocked_healing = session.handle_packet(ClientPacket::Magic {
        object_id,
        spell: Spell::Healing,
        direction: MirDirection::Right,
        target_id: object_id,
        location: origin.clone(),
        spell_target_lock: true,
    });
    assert_eq!(session.world_snapshot().player_mp, Some(after_shield_mp));
    assert!(blocked_healing
        .iter()
        .all(|packet| matches!(packet, ServerPacket::UserLocation { .. })));

    for _ in 0..10 {
        session.tick();
    }
    session
        .app
        .world_mut()
        .resource_mut::<SkillResource>()
        .skills
        .iter_mut()
        .filter(|skill| skill.key == "minor-heal")
        .for_each(|skill| skill.cooldown_ends_at = 0);

    let healing_packets = session.handle_packet(ClientPacket::Magic {
        object_id,
        spell: Spell::Healing,
        direction: MirDirection::Right,
        target_id: object_id,
        location: origin,
        spell_target_lock: true,
    });
    for _ in 0..5 {
        session.tick();
    }

    assert!(healing_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectEffect { info }
            if info.object_id == object_id && info.effect == 3
    )));
    assert!(
        session
            .app
            .world()
            .entity(player)
            .get::<PlayerVitals>()
            .expect("player vitals")
            .hp
            > 20
    );
}

#[test]
fn skill_snapshot_exposes_cast_kind_and_offensive_metadata() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    {
        let mut skills = session.app.world_mut().resource_mut::<SkillResource>();
        skills
            .skills
            .push(super::crystal_skill_state("Fencing", 2).expect("Fencing skill"));
        skills
            .skills
            .push(super::crystal_skill_state("FireBall", 1).expect("FireBall skill"));
        skills
            .skills
            .push(super::crystal_skill_state("MagicShield", 1).expect("MagicShield skill"));
    }
    let snapshot = session.world_snapshot();

    let fencing = snapshot
        .known_skills
        .iter()
        .find(|skill| skill.spell.as_deref() == Some("Fencing"))
        .expect("Fencing snapshot");
    assert_eq!(fencing.cast_kind, "passive");
    assert!(!fencing.offensive);
    let fireball = snapshot
        .known_skills
        .iter()
        .find(|skill| skill.spell.as_deref() == Some("FireBall"))
        .expect("FireBall snapshot");
    assert_eq!(fireball.cast_kind, "target");
    assert!(fireball.offensive);
    let shield = snapshot
        .known_skills
        .iter()
        .find(|skill| skill.spell.as_deref() == Some("MagicShield"))
        .expect("MagicShield snapshot");
    assert_eq!(shield.cast_kind, "self");
    assert!(!shield.offensive);
}

#[test]
fn magic_packet_progresses_user_magic_and_emits_level_packets() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_active_character_class_gender_level(&mut session, MirClass::Wizard, MirGender::Male, 7);
    set_current_player_mp(&mut session, 500);
    let player = player_entity(session.app.world()).expect("player entity");
    let origin = find_combat_origin_box(&session, player, 2, 2, 2, 2);
    set_player_position(&mut session, origin.clone());
    let target_tile = Point {
        x: origin.x + 1,
        y: origin.y,
    };
    let target_object_id = 98_002;
    spawn_crystal_monster_for_test(
        &mut session,
        target_object_id,
        "Yob",
        target_tile.clone(),
        MirDirection::Left,
        true,
    );
    let magic = mir2_game_data::crystal_magic_by_spell("FireBall").expect("FireBall magic");
    let mut fireball = super::crystal_skill_state("FireBall", 0).expect("fireball magic");
    fireball.experience = magic.need1.saturating_sub(1);
    session
        .app
        .world_mut()
        .resource_mut::<SkillResource>()
        .skills
        .push(fireball);
    let object_id = current_player_object_id(session.app.world()).expect("player object id");

    let packets = session.handle_packet(ClientPacket::Magic {
        object_id,
        spell: Spell::FireBall,
        direction: MirDirection::Right,
        target_id: target_object_id,
        location: target_tile,
        spell_target_lock: true,
    });
    let snapshot = session.world_snapshot();

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::MagicDelay {
            object_id: packet_object_id,
            spell: Spell::FireBall,
            delay
        } if *packet_object_id == object_id && *delay > 0
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::MagicLeveled {
            object_id: packet_object_id,
            spell: Spell::FireBall,
            level: 1,
            ..
        } if *packet_object_id == object_id
    )));
    let fireball = snapshot
        .known_skills
        .iter()
        .find(|skill| skill.key == "fireball")
        .expect("fireball skill snapshot");
    assert_eq!(fireball.level, 1);
    assert!(fireball.delay_ms > 0);
    assert!(fireball.cast_time_ms >= 0);
}

#[test]
fn magic_packet_crystal_skill_gain_multiplier_scales_practice_experience() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    set_active_character_class_gender_level(&mut session, MirClass::Wizard, MirGender::Male, 7);
    let skill_gain_expires_at = runtime_tick(session.app.world()).saturating_add(60);
    session
        .app
        .world_mut()
        .resource_mut::<BuffResource>()
        .buffs
        .push(super::BuffState {
            key: "skill-gain".to_string(),
            name: "Skill Gain".to_string(),
            description: "Crystal skill gain multiplier is active.".to_string(),
            expires_at_tick: skill_gain_expires_at,
            attack_bonus: 0,
            defence_bonus: 0,
            stats: vec![UserItemStat {
                stat: super::CRYSTAL_STAT_SKILL_GAIN_MULTIPLIER,
                value: 3,
            }],
        });
    set_current_player_mp(&mut session, 500);
    let player = player_entity(session.app.world()).expect("player entity");
    let origin = find_combat_origin_box(&session, player, 2, 2, 2, 2);
    set_player_position(&mut session, origin.clone());
    let target_tile = Point {
        x: origin.x + 1,
        y: origin.y,
    };
    let target_object_id = 98_003;
    spawn_crystal_monster_for_test(
        &mut session,
        target_object_id,
        "Yob",
        target_tile.clone(),
        MirDirection::Left,
        true,
    );
    session
        .app
        .world_mut()
        .resource_mut::<SkillResource>()
        .skills
        .push(super::crystal_skill_state("FireBall", 0).expect("fireball magic"));
    let object_id = current_player_object_id(session.app.world()).expect("player object id");
    let expected_base_gain = 1
        + ((runtime_tick(session.app.world())
            + u64::from(object_id)
            + u64::from(Spell::FireBall as u8))
            % 3) as u16;

    let packets = session.handle_packet(ClientPacket::Magic {
        object_id,
        spell: Spell::FireBall,
        direction: MirDirection::Right,
        target_id: target_object_id,
        location: target_tile,
        spell_target_lock: true,
    });

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::MagicLeveled {
            object_id: packet_object_id,
            spell: Spell::FireBall,
            level: 0,
            experience,
        } if *packet_object_id == object_id && *experience == expected_base_gain * 3
    )));
    let fireball = session
        .world_snapshot()
        .known_skills
        .into_iter()
        .find(|skill| skill.key == "fireball")
        .expect("fireball skill snapshot");
    assert_eq!(fireball.experience, expected_base_gain * 3);
}

