#[test]
fn casting_summon_shinsu_spawns_friendly_player_pet() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    // SummonShinsu consumes an amulet (crystal_spell_required_items_available).
    equip_crystal_item(&mut session, "Amulet", EquipmentSlot::Amulet);
    set_player_position(&mut session, Point { x: 333, y: 267 });

    let cast_packets = session.cast_skill("summon-shinsu");
    assert!(!cast_packets.iter().any(
        |packet| matches!(packet, ServerPacket::Chat { message, .. } if message.contains("Summon"))
    ));

    let spawn_packets = session.tick();
    assert!(spawn_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectMonster { info }
            if info.name == "Shinsu" && info.extra
    )));

    let shinsu = find_monster_entity_by(&session, |name, _, _| name == "Shinsu");
    let agent = session
        .app
        .world()
        .entity(shinsu)
        .get::<MonsterAgent>()
        .expect("shinsu agent");
    let summoned = session
        .app
        .world()
        .entity(shinsu)
        .get::<SummonedMonster>()
        .expect("shinsu summoned metadata");
    assert!(!agent.hostile_to_player);
    assert_eq!(agent.disposition, WorldEntityDisposition::Friendly);
    assert_eq!(
        summoned.summoner_object_id,
        current_player_object_id(session.app.world()).expect("player object id")
    );
}

#[test]
fn casting_summon_shinsu_recalls_existing_pet() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    // SummonShinsu consumes an amulet (crystal_spell_required_items_available).
    equip_crystal_item(&mut session, "Amulet", EquipmentSlot::Amulet);
    let first_position = Point { x: 333, y: 267 };
    let second_position = Point { x: 360, y: 267 };
    set_player_position(&mut session, first_position.clone());

    let _ = session.cast_skill("summon-shinsu");
    let _ = session.tick();
    let shinsu = find_monster_entity_by(&session, |name, _, _| name == "Shinsu");
    let before_recall =
        entity_position(session.app.world(), shinsu).expect("initial shinsu position");

    let skill_index = session
        .app
        .world()
        .resource::<SkillResource>()
        .skills
        .iter()
        .position(|skill| skill.key == "summon-shinsu")
        .expect("summon-shinsu skill");
    session
        .app
        .world_mut()
        .resource_mut::<SkillResource>()
        .skills[skill_index]
        .cooldown_ends_at = 0;

    set_player_position(&mut session, second_position.clone());
    let _ = session.cast_skill("summon-shinsu");
    let shinsu_position =
        entity_position(session.app.world(), shinsu).expect("recalled shinsu position");

    assert_ne!(shinsu_position, before_recall);
    #[allow(deprecated)]
    let shinsu_count = session
        .app
        .world()
        .iter_entities()
        .filter(|entity| {
            entity
                .get::<DisplayName>()
                .map(|name| name.value == "Shinsu")
                .unwrap_or(false)
        })
        .count();
    assert_eq!(shinsu_count, 1);
}

