#[test]
fn friendly_vampire_spider_death_explosion_has_no_runtime_defeat_chat_and_hits_nearby_hostile_monster(
) {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let player_origin = Point { x: 333, y: 267 };
    set_player_position(&mut session, player_origin.clone());

    let hostile = find_monster_entity_by(&session, |name, _, _| name == "Field Wasp");
    set_entity_position(
        &mut session,
        hostile,
        Point {
            x: player_origin.x + 2,
            y: player_origin.y,
        },
    );

    let _ = session.cast_skill("summon-vampire");
    let _ = session.tick();
    let vampire = find_monster_entity_by(&session, |name, _, _| name == "VampireSpider");
    set_entity_position(
        &mut session,
        vampire,
        Point {
            x: player_origin.x + 1,
            y: player_origin.y,
        },
    );

    let current_tick = runtime_tick(session.app.world());
    let mut packets = Vec::new();
    let _ = super::damage_monster_entity(
        session.app.world_mut(),
        vampire,
        i32::MAX,
        current_tick,
        &mut packets,
    );
    assert!(!packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));
    let next_packets = session.tick();
    assert!(next_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectHealth { info } if info.object_id == 3002 && info.percent < 100
    )));
    assert!(!next_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));
}

