#[test]
fn friendly_shinsu_line_attack_hits_second_monster_in_front() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    // SummonShinsu consumes an amulet (crystal_spell_required_items_available).
    equip_crystal_item(&mut session, "Amulet", EquipmentSlot::Amulet);
    let origin = Point { x: 333, y: 267 };
    set_player_position(&mut session, origin.clone());

    let wasp = find_monster_entity_by(&session, |name, _, _| name == "Field Wasp");
    set_entity_position(
        &mut session,
        wasp,
        Point {
            x: origin.x + 2,
            y: origin.y,
        },
    );

    let current_tick = runtime_tick(session.app.world());
    let second_object_id = 98_930_u32;
    session.app.world_mut().spawn((
        WorldObject,
        Monster,
        ObjectId(second_object_id),
        DisplayName::literal("Line Target"),
        Position(Point {
            x: origin.x + 1,
            y: origin.y,
        }),
        Facing(MirDirection::Left),
        MonsterAgent {
            image: 43,
            dead: false,
            patrol_origin: Point {
                x: origin.x + 1,
                y: origin.y,
            },
            ai: 0,
            disposition: WorldEntityDisposition::Hostile,
            hostile_to_player: true,
            tracking_player: false,
            view_range: 7,
            can_wander: false,
            move_interval_ticks: 1,
            attack_interval_ticks: 10,
            next_move_tick: current_tick,
            next_attack_tick: current_tick,
            route: Vec::new(),
            route_index: 0,
            route_waiting: false,
            next_route_tick: current_tick,
        },
        MonsterVitals { hp: 20, max_hp: 20 },
    ));
    sync_visible_objects(&mut session);

    let _ = session.cast_skill("summon-shinsu");
    let _ = session.tick();
    let shinsu = find_monster_entity_by(&session, |name, _, _| name == "Shinsu");
    set_entity_position(&mut session, shinsu, origin.clone());
    session
        .app
        .world_mut()
        .entity_mut(shinsu)
        .insert(Facing(MirDirection::Right));

    let _ = session.tick();
    let hit_packets = session.tick();
    assert!(hit_packets.iter().any(|packet| matches!(
            packet,
            ServerPacket::ObjectHealth { info } if info.object_id == second_object_id && info.percent < 100
        )));
    assert!(hit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ObjectHealth { info } if info.object_id == 3002 && info.percent < 100
    )));
}

