#[test]
fn guild_war_lifecycle_expires_war_and_emits_end_chat_and_colour_state() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session.stage5_command("guild.create", vec!["BichonGuard".to_string()]);
    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        stage5.stage5_systems.guild.storage_gold = 3_000;
        stage5
            .stage5_systems
            .guild
            .known_guilds
            .push("MinerLeague".to_string());
    }
    session.handle_packet(ClientPacket::GuildWarReturn {
        name: "MinerLeague".to_string(),
    });
    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        stage5
            .stage5_systems
            .guild
            .active_war_ticks_remaining
            .insert("MinerLeague".to_string(), 1);
    }
    super::set_runtime_tick(session.app.world_mut(), 59);

    let packets = session.tick();
    let end_message = super::format_localized_text(
        mir2_game_data::LanguageCode::English,
        "server.WarEndedWithGuild",
        ["MinerLeague".to_string()],
    );

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            message,
            chat_type: ChatType::Guild,
        } if message == &end_message
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ColourChanged { name_colour_argb } if *name_colour_argb == -1
    )));
    assert!(!super::stage5_guild_is_at_war_with(
        session.app.world(),
        "MinerLeague"
    ));
    let snapshot = session.world_snapshot();
    assert!(snapshot.stage5_systems.guild.active_wars.is_empty());
    assert!(snapshot
        .stage5_systems
        .guild
        .active_war_ticks_remaining
        .is_empty());
    assert!(snapshot
        .stage5_systems
        .guild
        .war_broadcasts
        .iter()
        .any(|message| message == &end_message));
}

#[test]
fn guild_alliance_commands_use_can_alter_alliance_and_update_ally_count() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session.stage5_command("guild.create", vec!["BichonGuard".to_string()]);
    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        let guild = &mut stage5.stage5_systems.guild;
        guild.rank = "Members".to_string();
        guild.permissions = vec!["alterAlliance".to_string()];
        guild.known_guilds.push("MinerLeague".to_string());
    }

    let member_packets = session.handle_packet(ClientPacket::RequestGuildInfo { info_type: 1 });
    assert!(member_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GuildMemberChange { ranks, .. }
            if matches!(ranks.first(), Some(rank) if rank.index == 1 && rank.options == 32)
    )));

    let ally_packets = session.stage5_command("guild.ally", vec!["MinerLeague".to_string()]);
    assert_eq!(
        ally_packets,
        vec![ServerPacket::Chat {
            message: "Alliance formed with MinerLeague.".to_string(),
            chat_type: ChatType::Guild,
        }]
    );
    let snapshot = session.world_snapshot();
    assert_eq!(
        snapshot.stage5_systems.guild.allied_guilds,
        vec!["MinerLeague".to_string()]
    );
    assert_eq!(snapshot.stage5_systems.guild.ally_count, 1);
    assert_eq!(
        snapshot.stage5_systems.guild.alliance_broadcasts,
        vec!["Alliance formed with MinerLeague.".to_string()]
    );

    let duplicate_packets = session.stage5_command("guild.ally", vec!["minerleague".to_string()]);
    assert!(duplicate_packets.is_empty());
    let snapshot = session.world_snapshot();
    assert_eq!(
        snapshot.stage5_systems.guild.allied_guilds,
        vec!["MinerLeague".to_string()]
    );
    assert_eq!(snapshot.stage5_systems.guild.ally_count, 1);

    let unally_packets = session.stage5_command("guild.unally", vec!["minerleague".to_string()]);
    assert_eq!(
        unally_packets,
        vec![ServerPacket::Chat {
            message: "Alliance ended with MinerLeague.".to_string(),
            chat_type: ChatType::Guild,
        }]
    );
    let snapshot = session.world_snapshot();
    assert!(snapshot.stage5_systems.guild.allied_guilds.is_empty());
    assert_eq!(snapshot.stage5_systems.guild.ally_count, 0);
    assert!(snapshot
        .stage5_systems
        .guild
        .alliance_broadcasts
        .iter()
        .any(|message| message == "Alliance ended with MinerLeague."));
}

#[test]
fn guild_alliance_request_info_exposes_count_list_and_recent_broadcasts() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session.stage5_command("guild.create", vec!["BichonGuard".to_string()]);
    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        let guild = &mut stage5.stage5_systems.guild;
        guild.known_guilds.push("MinerLeague".to_string());
    }

    session.stage5_command("guild.ally", vec!["MinerLeague".to_string()]);
    let info_packets = session.handle_packet(ClientPacket::RequestGuildInfo { info_type: 1 });
    let guild_messages = info_packets
        .iter()
        .filter_map(|packet| match packet {
            ServerPacket::Chat {
                message,
                chat_type: ChatType::Guild,
            } => Some(message.as_str()),
            _ => None,
        })
        .collect::<Vec<_>>();

    assert!(info_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::GuildMemberChange { status: 255, .. })));
    assert!(guild_messages
        .iter()
        .any(|message| *message == "AllyCount: 1"));
    assert!(guild_messages
        .iter()
        .any(|message| *message == "AllyGuilds: MinerLeague"));
    assert!(guild_messages
        .iter()
        .any(|message| { *message == "AllianceBroadcast: Alliance formed with MinerLeague." }));

    session.stage5_command("guild.unally", vec!["minerleague".to_string()]);
    let unally_info_packets =
        session.handle_packet(ClientPacket::RequestGuildInfo { info_type: 1 });
    let unally_messages = unally_info_packets
        .iter()
        .filter_map(|packet| match packet {
            ServerPacket::Chat {
                message,
                chat_type: ChatType::Guild,
            } => Some(message.as_str()),
            _ => None,
        })
        .collect::<Vec<_>>();
    let ally_guilds_line = unally_messages
        .iter()
        .find(|message| message.starts_with("AllyGuilds:"))
        .copied()
        .expect("unally info should include the current ally list");

    assert!(unally_messages
        .iter()
        .any(|message| *message == "AllyCount: 0"));
    assert_eq!(ally_guilds_line, "AllyGuilds: None");
    assert!(unally_messages
        .iter()
        .any(|message| { *message == "AllianceBroadcast: Alliance ended with MinerLeague." }));
}

#[test]
fn guild_alliance_runtime_state_does_not_rehydrate_from_save_like_crystal() {
    let temp_dir = unique_runtime_temp_dir("guild-alliance-runtime");
    let store_path = temp_dir.join("accounts.json");
    let config = SimulationConfig::default().with_account_store_path(store_path.clone());
    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::Login {
        account_id: "guild-alliance-runtime".to_string(),
        password: "demo".to_string(),
    });
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session.stage5_command("guild.create", vec!["BichonGuard".to_string()]);
    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        stage5
            .stage5_systems
            .guild
            .known_guilds
            .push("MinerLeague".to_string());
    }

    session.stage5_command("guild.ally", vec!["MinerLeague".to_string()]);
    assert_eq!(
        session.world_snapshot().stage5_systems.guild.allied_guilds,
        vec!["MinerLeague".to_string()]
    );
    session.save_active_character();

    let mut reloaded =
        SimulationSession::new(SimulationConfig::default().with_account_store_path(store_path));
    reloaded.handle_packet(ClientPacket::Login {
        account_id: "guild-alliance-runtime".to_string(),
        password: "demo".to_string(),
    });
    reloaded.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let snapshot = reloaded.world_snapshot();
    assert_eq!(snapshot.stage5_systems.guild.name, "BichonGuard");
    assert!(snapshot
        .stage5_systems
        .guild
        .known_guilds
        .iter()
        .any(|name| name == "MinerLeague"));
    assert!(snapshot.stage5_systems.guild.allied_guilds.is_empty());
    assert_eq!(snapshot.stage5_systems.guild.ally_count, 0);
    assert!(snapshot.stage5_systems.guild.alliance_broadcasts.is_empty());

    let info_packets = reloaded.handle_packet(ClientPacket::RequestGuildInfo { info_type: 1 });
    assert!(!info_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            message,
            chat_type: ChatType::Guild,
        } if message.contains("AllyCount")
            || message.contains("AllyGuilds")
            || message.contains("AllianceBroadcast")
    )));
}

#[test]
fn guild_alliance_rejects_missing_self_permission_and_active_war_without_mutation() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session.stage5_command("guild.create", vec!["BichonGuard".to_string()]);
    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        let guild = &mut stage5.stage5_systems.guild;
        guild.rank = "Members".to_string();
        guild.permissions.clear();
        guild.known_guilds.push("MinerLeague".to_string());
    }

    let permission_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.NoCorrectGuildRank",
        "server.NoCorrectGuildRank",
    );
    let permission_packets = session.stage5_command("guild.ally", vec!["MinerLeague".to_string()]);
    assert!(permission_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &permission_message
    )));
    assert!(session
        .world_snapshot()
        .stage5_systems
        .guild
        .allied_guilds
        .is_empty());
    let denied_info_packets =
        session.handle_packet(ClientPacket::RequestGuildInfo { info_type: 1 });
    assert!(!denied_info_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            message,
            chat_type: ChatType::Guild,
        } if message.contains("AllyCount")
            || message.contains("AllyGuilds")
            || message.contains("MinerLeague")
    )));

    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        let guild = &mut stage5.stage5_systems.guild;
        guild.rank = "Guild Chief".to_string();
        guild.permissions.push("alterAlliance".to_string());
    }

    let missing_message = super::format_localized_text(
        mir2_game_data::LanguageCode::English,
        "server.GuildNotFound",
        ["UnknownGuild".to_string()],
    );
    let missing_packets = session.stage5_command("guild.ally", vec!["UnknownGuild".to_string()]);
    assert!(missing_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &missing_message
    )));

    let self_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.CannotWarOwnGuild",
        "server.CannotWarOwnGuild",
    );
    let self_packets = session.stage5_command("guild.ally", vec!["BichonGuard".to_string()]);
    assert!(self_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &self_message
    )));

    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        stage5
            .stage5_systems
            .guild
            .active_wars
            .push("MinerLeague".to_string());
    }
    let war_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.AlreadyAtWarWithGuild",
        "server.AlreadyAtWarWithGuild",
    );
    let war_packets = session.stage5_command("guild.ally", vec!["minerleague".to_string()]);
    assert!(war_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &war_message
    )));

    let snapshot = session.world_snapshot();
    assert!(snapshot.stage5_systems.guild.allied_guilds.is_empty());
    assert_eq!(snapshot.stage5_systems.guild.ally_count, 0);
    assert!(snapshot.stage5_systems.guild.alliance_broadcasts.is_empty());
    let war_info_packets = session.handle_packet(ClientPacket::RequestGuildInfo { info_type: 1 });
    assert!(!war_info_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            message,
            chat_type: ChatType::Guild,
        } if message.contains("AllyCount")
            || message.contains("AllyGuilds")
            || message.contains("MinerLeague")
    )));
}

#[test]
fn guild_territory_packets_page_and_purchase_use_bank_gold_with_rollback() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session.stage5_command("guild.create", vec!["BichonGuard".to_string()]);
    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        stage5.stage5_systems.guild.storage_gold = 4_999;
        stage5.stage5_systems.guild_territory.owner = "MinerLeague".to_string();
        stage5.stage5_systems.guild_territory.leader = "MinerChief".to_string();
        stage5.stage5_systems.guild_territory.leader2 = "MinerDeputy".to_string();
        stage5.stage5_systems.guild_territory.price = 5_000;
        stage5.stage5_systems.guild_territory.rental_days_left = 7;
    }

    let page_packets = session.handle_packet(ClientPacket::GuildTerritoryPage { page: 0 });
    assert!(page_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GuildTerritoryPage { length, listings }
            if *length == 1
                && matches!(listings.first(), Some(listing)
                    if listing.owner == "MinerLeague"
                        && listing.price == 5_000
                        && listing.days == 7)
    )));

    let insufficient_packets = session.handle_packet(ClientPacket::PurchaseGuildTerritory {
        owner: "MinerLeague".to_string(),
    });
    let insufficient_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.InsufficientFunds",
        "server.InsufficientFunds",
    );
    assert!(insufficient_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &insufficient_message
    )));
    let snapshot = session.world_snapshot();
    assert_eq!(snapshot.stage5_systems.guild.storage_gold, 4_999);
    assert_eq!(snapshot.stage5_systems.guild_territory.owner, "MinerLeague");
    assert!(!snapshot.stage5_systems.guild_territory.owned);

    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        stage5.stage5_systems.guild.storage_gold = 5_000;
    }
    let purchase_packets = session.handle_packet(ClientPacket::PurchaseGuildTerritory {
        owner: "MinerLeague".to_string(),
    });
    assert!(purchase_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GuildStorageGoldChange {
            amount: 5_000,
            change_type: 2,
            ..
        }
    )));
    let success_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.GuildTerritoryPurchaseProcess24Hrs",
        "server.GuildTerritoryPurchaseProcess24Hrs",
    );
    assert!(purchase_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &success_message
    )));
    let snapshot = session.world_snapshot();
    assert_eq!(snapshot.stage5_systems.guild.storage_gold, 0);
    assert!(snapshot.stage5_systems.guild_territory.owned);
    assert_eq!(snapshot.stage5_systems.guild_territory.owner, "BichonGuard");
    assert_eq!(snapshot.stage5_systems.guild_territory.price, 0);
}

#[test]
fn group_packets_update_stage5_group_and_emit_crystal_surfaces() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let switch_packets = session.handle_packet(ClientPacket::SwitchGroup { allow_group: true });
    assert!(switch_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::SwitchGroup { allow_group: true })));

    let add_packets = session.handle_packet(ClientPacket::AddMember {
        name: "Miner".to_string(),
    });
    assert!(add_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::AddMember { name } if name == "Scout")));
    assert!(add_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::AddMember { name } if name == "Miner")));
    assert!(add_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GroupMembersMap {
            player_name,
            player_map,
        } if player_name == "Miner" && !player_map.is_empty()
    )));
    assert!(add_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::SendMemberLocation {
            member_name,
            member_location,
        } if member_name == "Miner" && member_location.x > 0 && member_location.y > 0
    )));
    assert_eq!(
        session.world_snapshot().stage5_systems.group.members,
        vec!["Scout".to_string(), "Miner".to_string()]
    );

    let delete_packets = session.handle_packet(ClientPacket::DelMember {
        name: "Miner".to_string(),
    });
    assert!(delete_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::DeleteGroup)));
    assert!(session
        .world_snapshot()
        .stage5_systems
        .group
        .members
        .is_empty());

    let add_again_packets = session.handle_packet(ClientPacket::AddMember {
        name: "Miner".to_string(),
    });
    assert!(add_again_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::AddMember { name } if name == "Miner")));
    let disable_packets = session.handle_packet(ClientPacket::SwitchGroup { allow_group: false });
    assert!(disable_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::SwitchGroup { allow_group: false })));
    assert!(disable_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::DeleteGroup)));
    let group = session.world_snapshot().stage5_systems.group;
    assert!(!group.allow_group);
    assert!(group.members.is_empty());
}

#[test]
fn stage5_trade_shop_and_auction_are_transactional() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let trade_successful_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.TradeSuccessful",
        "server.TradeSuccessful",
    );
    let starting_gold = session.world_snapshot().gold;

    session.stage5_command("trade.start", vec!["Trader".to_string()]);
    session.stage5_command("trade.offerItem", vec!["red-potion".to_string()]);
    session.stage5_command("trade.offerGold", vec!["10".to_string()]);
    let trade_packets = session.stage5_command("trade.accept", Vec::new());
    let after_trade = session.world_snapshot();
    assert!(trade_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &trade_successful_message
    )));
    assert!(after_trade
        .stage5_systems
        .trade
        .as_ref()
        .is_some_and(|trade| { trade.completed && trade.accepted && trade.offered_gold == 10 }));
    assert_eq!(after_trade.gold, starting_gold - 10);

    let shop_packets =
        session.stage5_command("shop.buy", vec!["red-potion".to_string(), "25".to_string()]);
    let after_shop = session.world_snapshot();
    let bought_for_gold_message = super::format_localized_text(
        super::LanguageCode::English,
        "server.BoughtItemForGold",
        ["red-potion".to_string(), "25".to_string()],
    );
    assert!(shop_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &bought_for_gold_message
    )));
    assert!(after_shop
        .inventory_items
        .iter()
        .any(|item| item.key == "red-potion" && item.quantity >= 2));
    assert_eq!(after_shop.gold, starting_gold - 35);

    session
        .app
        .world_mut()
        .resource_mut::<PlayerRuntimeResource>()
        .credit = 15;
    let credit_packets = session.stage5_command(
        "shop.buyCredit",
        vec!["credit-shop-item".to_string(), "5".to_string()],
    );
    let after_credit_shop = session.world_snapshot();
    assert!(credit_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoseCredit { credit: 5 })));
    assert_eq!(after_credit_shop.credit, 10);
    assert!(after_credit_shop
        .stage5_systems
        .mail
        .iter()
        .any(|mail| mail.from == "Gameshop"
            && mail.items == vec!["credit-shop-item".to_string()]
            && !mail.claimed));
    assert!(!after_credit_shop
        .inventory_items
        .iter()
        .any(|item| item.key == "credit-shop-item"));

    session.stage5_command(
        "auction.list",
        vec!["training-splinter".to_string(), "50".to_string()],
    );
    session.stage5_command("auction.buy", vec!["1".to_string()]);
    let after_auction = session.world_snapshot();
    assert!(after_auction
        .stage5_systems
        .auction
        .iter()
        .any(|listing| listing.id == 1 && listing.sold));
    assert!(after_auction
        .inventory_items
        .iter()
        .any(|item| item.key == "training-splinter"));
    assert_eq!(after_auction.gold, starting_gold - 85);
}

#[test]
fn stage5_expired_auction_cannot_be_bought() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let not_found_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.NotFound",
        "server.NotFound",
    );
    let starting_gold = session.world_snapshot().gold;

    session.stage5_command(
        "auction.list",
        vec!["expired-auction".to_string(), "50".to_string()],
    );
    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        stage5.stage5_systems.auction[0].expired = true;
    }

    let packets = session.stage5_command("auction.buy", vec!["1".to_string()]);
    let after_buy = session.world_snapshot();

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));
    assert_eq!(after_buy.gold, starting_gold);
    assert!(after_buy.stage5_systems.auction.iter().any(|listing| {
        listing.id == 1 && listing.expired && !listing.sold && !listing.cancelled
    }));
    assert!(!after_buy
        .inventory_items
        .iter()
        .any(|item| item.key == "expired-auction"));
}

#[test]
fn stage5_credit_shop_mails_purchase_and_claim_transfers_attachment() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let bought_for_credit_message = super::format_localized_text(
        mir2_game_data::LanguageCode::English,
        "server.BoughtItemForCredit",
        ["mail-credit-item".to_string(), "5".to_string()],
    );
    session
        .app
        .world_mut()
        .resource_mut::<PlayerRuntimeResource>()
        .credit = 10;

    let packets = session.stage5_command(
        "shop.buyCredit",
        vec!["mail-credit-item".to_string(), "5".to_string()],
    );
    let after_buy = session.world_snapshot();

    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoseCredit { credit: 5 })));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &bought_for_credit_message
    )));
    assert_eq!(after_buy.credit, 5);
    assert!(after_buy.stage5_systems.mail.iter().any(|mail| mail.id == 1
        && mail.from == "Gameshop"
        && mail.items == vec!["mail-credit-item".to_string()]
        && !mail.claimed));
    assert!(!after_buy
        .inventory_items
        .iter()
        .any(|item| item.key == "mail-credit-item"));

    session.stage5_command("mail.claim", vec!["1".to_string()]);
    let after_claim = session.world_snapshot();

    assert!(after_claim
        .stage5_systems
        .mail
        .iter()
        .any(|mail| mail.id == 1 && mail.claimed));
    assert!(after_claim
        .inventory_items
        .iter()
        .any(|item| item.key == "mail-credit-item"));
}

#[test]
fn crystal_game_shop_credit_buy_uses_manifest_and_mail_delivery() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    session
        .app
        .world_mut()
        .resource_mut::<PlayerRuntimeResource>()
        .credit = 500;

    let packets =
        session.stage5_command("gameShop.buyCredit", vec!["1".to_string(), "1".to_string()]);
    let snapshot = session.world_snapshot();

    assert!(packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoseCredit { credit: 220 })));
    assert_eq!(snapshot.credit, 280);
    assert!(snapshot.stage5_systems.mail.iter().any(|mail| {
        mail.from == "Gameshop"
            && mail.items == vec!["crystal-item-1268".to_string()]
            && !mail.claimed
    }));
    assert!(!snapshot
        .inventory_items
        .iter()
        .any(|item| item.key == "crystal-item-1268"));
}

#[test]
fn stage5_trade_shop_and_auction_cancel_error_paths_preserve_gold() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let low_gold_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.LowGold",
        "server.LowGold",
    );
    let enough_currency_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.YouDontHaveEnoughCurrency",
        "server.YouDontHaveEnoughCurrency",
    );
    let invalid_trade_gold_message = super::format_localized_text(
        mir2_game_data::LanguageCode::English,
        "server.InvalidPacketReceived",
        ["trade.offerGold".to_string()],
    );
    let invalid_auction_buy_message = super::format_localized_text(
        mir2_game_data::LanguageCode::English,
        "server.InvalidPacketReceived",
        ["auction.buy".to_string()],
    );
    let invalid_auction_cancel_message = super::format_localized_text(
        mir2_game_data::LanguageCode::English,
        "server.InvalidPacketReceived",
        ["auction.cancel".to_string()],
    );
    let invalid_stage5_message = super::format_localized_text(
        mir2_game_data::LanguageCode::English,
        "server.InvalidPacketReceived",
        ["stage5.invalid".to_string()],
    );
    let not_found_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.NotFound",
        "server.NotFound",
    );
    let starting_gold = session.world_snapshot().gold;

    let invalid_stage5_packets = session.stage5_command("stage5.invalid", Vec::new());
    assert!(invalid_stage5_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &invalid_stage5_message
    )));

    let inactive_trade_gold_packets =
        session.stage5_command("trade.offerGold", vec!["1".to_string()]);
    assert!(inactive_trade_gold_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));
    let inactive_trade_item_packets =
        session.stage5_command("trade.offerItem", vec!["red-potion".to_string()]);
    assert!(inactive_trade_item_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));
    let inactive_trade_accept_packets = session.stage5_command("trade.accept", Vec::new());
    assert!(inactive_trade_accept_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));
    let after_inactive_trade = session.world_snapshot();
    assert_eq!(after_inactive_trade.gold, starting_gold);
    assert!(after_inactive_trade.stage5_systems.trade.is_none());

    session.stage5_command("trade.start", vec!["Trader".to_string()]);
    let missing_trade_gold_packets = session.stage5_command("trade.offerGold", Vec::new());
    assert!(missing_trade_gold_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &invalid_trade_gold_message
    )));
    let failed_trade_packets =
        session.stage5_command("trade.offerGold", vec!["999999".to_string()]);
    let after_failed_trade = session.world_snapshot();
    assert!(failed_trade_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &low_gold_message
    )));
    assert_eq!(after_failed_trade.gold, starting_gold);
    assert!(after_failed_trade
        .stage5_systems
        .trade
        .as_ref()
        .is_some_and(|trade| trade.offered_gold == 0 && !trade.completed));
    session.stage5_command("trade.offerGold", vec!["50".to_string()]);
    session.stage5_command("trade.cancel", Vec::new());
    let after_cancel = session.world_snapshot();
    assert!(after_cancel.stage5_systems.trade.is_none());
    assert_eq!(after_cancel.gold, starting_gold);

    let failed_shop_packets = session.stage5_command(
        "shop.buy",
        vec!["expensive-relic".to_string(), "999999".to_string()],
    );
    let after_failed_shop = session.world_snapshot();
    assert!(failed_shop_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &low_gold_message
    )));
    assert_eq!(after_failed_shop.gold, starting_gold);
    assert!(!after_failed_shop
        .inventory_items
        .iter()
        .any(|item| item.key == "expensive-relic"));

    session
        .app
        .world_mut()
        .resource_mut::<PlayerRuntimeResource>()
        .credit = 3;
    let failed_credit_packets = session.stage5_command(
        "shop.buyCredit",
        vec!["credit-relic".to_string(), "5".to_string()],
    );
    let after_failed_credit_shop = session.world_snapshot();
    assert!(failed_credit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &enough_currency_message
    )));
    assert_eq!(after_failed_credit_shop.credit, 3);
    assert!(failed_credit_packets
        .iter()
        .all(|packet| !matches!(packet, ServerPacket::LoseCredit { .. })));
    assert!(after_failed_credit_shop.stage5_systems.mail.is_empty());
    assert!(!after_failed_credit_shop
        .inventory_items
        .iter()
        .any(|item| item.key == "credit-relic"));

    session.stage5_command(
        "auction.list",
        vec!["expensive-auction".to_string(), "999999".to_string()],
    );
    let missing_auction_buy_packets = session.stage5_command("auction.buy", Vec::new());
    assert!(missing_auction_buy_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &invalid_auction_buy_message
    )));
    let failed_auction_packets = session.stage5_command("auction.buy", vec!["1".to_string()]);
    let after_failed_auction = session.world_snapshot();
    assert!(failed_auction_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &low_gold_message
    )));
    assert_eq!(after_failed_auction.gold, starting_gold);
    assert!(after_failed_auction
        .stage5_systems
        .auction
        .iter()
        .any(|listing| listing.id == 1 && !listing.sold && !listing.cancelled));
    assert!(!after_failed_auction
        .inventory_items
        .iter()
        .any(|item| item.key == "expensive-auction"));

    session.stage5_command(
        "auction.list",
        vec!["training-splinter".to_string(), "50".to_string()],
    );
    let missing_auction_cancel_packets = session.stage5_command("auction.cancel", Vec::new());
    assert!(missing_auction_cancel_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &invalid_auction_cancel_message
    )));
    session.stage5_command("auction.cancel", vec!["2".to_string()]);
    session.stage5_command("auction.buy", vec!["2".to_string()]);
    let after_cancelled_auction = session.world_snapshot();
    assert_eq!(after_cancelled_auction.gold, starting_gold);
    assert!(after_cancelled_auction
        .stage5_systems
        .auction
        .iter()
        .any(|listing| listing.id == 2 && listing.cancelled && !listing.sold));
}

#[test]
fn stage5_missing_mail_trade_item_and_auction_use_not_found() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let not_found_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.NotFound",
        "server.NotFound",
    );
    let starting_gold = session.world_snapshot().gold;

    let mail_packets = session.stage5_command("mail.claim", vec!["999".to_string()]);
    assert!(mail_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));

    let trade_packets =
        session.stage5_command("trade.offerItem", vec!["missing-relic".to_string()]);
    assert!(trade_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));

    let auction_packets = session.stage5_command("auction.buy", vec!["999".to_string()]);
    assert!(auction_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));

    let snapshot = session.world_snapshot();
    assert_eq!(snapshot.gold, starting_gold);
    assert!(snapshot.stage5_systems.mail.is_empty());
    assert!(snapshot.stage5_systems.trade.is_none());
    assert!(snapshot.stage5_systems.auction.is_empty());
    assert!(!snapshot
        .inventory_items
        .iter()
        .any(|item| item.key == "missing-relic"));
}

#[test]
fn stage5_shop_and_auction_full_bag_preserve_gold_and_items() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let full_bag_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.YouCannotCarryAnymore",
        "server.YouCannotCarryAnymore",
    );
    session
        .app
        .world_mut()
        .resource_mut::<PlayerRuntimeResource>()
        .credit = 10;
    fill_all_bag_slots(&mut session);
    let starting_gold = session.world_snapshot().gold;
    let starting_credit = session.world_snapshot().credit;

    let shop_packets = session.stage5_command(
        "shop.buy",
        vec!["full-bag-shop".to_string(), "25".to_string()],
    );
    let after_shop = session.world_snapshot();
    assert!(shop_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &full_bag_message
    )));
    assert_eq!(after_shop.free_bag_slots, 0);
    assert_eq!(after_shop.gold, starting_gold);
    assert!(!after_shop
        .inventory_items
        .iter()
        .any(|item| item.key == "full-bag-shop"));

    let credit_packets = session.stage5_command(
        "shop.buyCredit",
        vec!["full-bag-credit-shop".to_string(), "5".to_string()],
    );
    let after_credit_shop = session.world_snapshot();
    assert_eq!(after_credit_shop.free_bag_slots, 0);
    assert_eq!(after_credit_shop.credit, starting_credit - 5);
    assert!(credit_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoseCredit { credit: 5 })));
    assert!(after_credit_shop
        .stage5_systems
        .mail
        .iter()
        .any(|mail| mail.from == "Gameshop"
            && mail.items == vec!["full-bag-credit-shop".to_string()]
            && !mail.claimed));
    assert!(!after_credit_shop
        .inventory_items
        .iter()
        .any(|item| item.key == "full-bag-credit-shop"));
    let claim_packets = session.stage5_command("mail.claim", vec!["1".to_string()]);
    let after_full_bag_claim = session.world_snapshot();
    assert!(claim_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &full_bag_message
    )));
    assert!(after_full_bag_claim
        .stage5_systems
        .mail
        .iter()
        .any(|mail| mail.id == 1 && !mail.claimed));
    assert!(!after_full_bag_claim
        .inventory_items
        .iter()
        .any(|item| item.key == "full-bag-credit-shop"));

    session.stage5_command(
        "auction.list",
        vec!["full-bag-auction".to_string(), "50".to_string()],
    );
    let auction_packets = session.stage5_command("auction.buy", vec!["1".to_string()]);
    let after_auction = session.world_snapshot();
    assert!(auction_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &full_bag_message
    )));
    assert_eq!(after_auction.gold, starting_gold);
    assert!(!after_auction
        .inventory_items
        .iter()
        .any(|item| item.key == "full-bag-auction"));
    assert!(after_auction
        .stage5_systems
        .auction
        .iter()
        .any(|listing| listing.id == 1 && !listing.sold && !listing.cancelled));

    session
        .app
        .world_mut()
        .resource_mut::<Stage5SystemsResource>()
        .stage5_systems
        .profession
        .ore = 1;
    let craft_packets = session.stage5_command("craft", vec!["full-bag-craft".to_string()]);
    let after_craft = session.world_snapshot();
    assert!(craft_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &full_bag_message
    )));
    assert_eq!(after_craft.stage5_systems.profession.ore, 1);
    assert!(!after_craft
        .inventory_items
        .iter()
        .any(|item| item.key == "full-bag-craft"));
}

#[test]
fn stage5_trade_disconnect_before_accept_preserves_gold() {
    let temp_dir = unique_runtime_temp_dir("stage5-trade-disconnect");
    let store_path = temp_dir.join("accounts.json");
    let config = SimulationConfig::default().with_account_store_path(store_path.clone());
    let mut session = SimulationSession::new(config);
    session.handle_packet(ClientPacket::Login {
        account_id: "stage5-trade-disconnect".to_string(),
        password: "demo".to_string(),
    });
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let starting_gold = session.world_snapshot().gold;

    session.stage5_command("trade.start", vec!["Trader".to_string()]);
    session.stage5_command("trade.offerGold", vec!["75".to_string()]);
    session.save_active_character();

    let mut reloaded =
        SimulationSession::new(SimulationConfig::default().with_account_store_path(store_path));
    reloaded.handle_packet(ClientPacket::Login {
        account_id: "stage5-trade-disconnect".to_string(),
        password: "demo".to_string(),
    });
    reloaded.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let after_reload = reloaded.world_snapshot();
    assert_eq!(after_reload.gold, starting_gold);
    assert!(after_reload
        .stage5_systems
        .trade
        .as_ref()
        .is_some_and(|trade| !trade.accepted && !trade.completed && trade.offered_gold == 75));

    reloaded.stage5_command("trade.accept", Vec::new());
    let after_accept = reloaded.world_snapshot();
    assert_eq!(after_accept.gold, starting_gold - 75);
}

#[test]
fn stage5_item_add_socket_emits_item_slot_size_changed() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    equip_bengal_tiger_with_socket_slots(&mut session, 4);

    let packets = session.stage5_command("item.addSocket", vec!["weapon".to_string()]);
    let snapshot = session.world_snapshot();

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ItemSlotSizeChanged {
            unique_id: 0,
            slot_size: 5
        }
    )));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            message
        } if message
            == &super::localized_text_or_fallback(
                super::LanguageCode::English,
                "server.ItemSocketsIncreased",
                "server.ItemSocketsIncreased",
            )
    )));
    assert!(snapshot.equipment_items.iter().any(|item| {
        item.slot == EquipmentSlot::Weapon && item.name == "BengalTiger" && item.socket_slots == 5
    }));
}

#[test]
fn stage5_qa_damage_equipment_emits_dura_changed_for_smoke_setup() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    equip_crystal_item(&mut session, "Dagger", EquipmentSlot::Weapon);
    let before = session
        .world_snapshot()
        .equipment_items
        .into_iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("weapon should be equipped")
        .durability_current;

    let packets = session.stage5_command(
        "qa.damageEquipment",
        vec!["weapon".to_string(), "7".to_string()],
    );
    let snapshot = session.world_snapshot();
    let after = snapshot
        .equipment_items
        .iter()
        .find(|item| item.slot == EquipmentSlot::Weapon)
        .expect("weapon should remain equipped")
        .durability_current;

    assert_eq!(after, before.saturating_sub(7));
    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::DuraChanged {
            unique_id: 0,
            current_dura
        } if *current_dura == after
    )));
}

