#[test]
fn stage5_item_add_socket_consumes_source_item_on_success() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    equip_bengal_tiger_with_socket_slots(&mut session, 4);
    add_socket_source_test_item(&mut session, 31, 2);

    let packets = session.stage5_command(
        "item.addSocket",
        vec!["weapon".to_string(), "stage5-socket-source".to_string()],
    );
    let snapshot = session.world_snapshot();

    assert!(packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::ItemSlotSizeChanged {
            unique_id: 0,
            slot_size: 5
        }
    )));
    assert!(snapshot
        .inventory_items
        .iter()
        .any(|item| { item.key == "stage5-socket-source" && item.quantity == 1 }));
    assert!(snapshot.equipment_items.iter().any(|item| {
        item.slot == EquipmentSlot::Weapon && item.name == "BengalTiger" && item.socket_slots == 5
    }));
}

