#[test]
fn stage5_conquest_event_hero_mining_and_crafting_flow() {
    let mut unstarted_session = SimulationSession::new(SimulationConfig::default());
    let not_found_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.NotFound",
        "server.NotFound",
    );
    let missing_player_packets =
        unstarted_session.stage5_command("event.spawn", vec!["BugBat".to_string()]);
    assert!(missing_player_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));

    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let crafting_failed_message = mir2_game_data::localized_text_or_fallback(
        mir2_game_data::LanguageCode::English,
        "server.CraftingAttemptFailed",
        "server.CraftingAttemptFailed",
    );

    session.stage5_command("guild.create", vec!["BichonGuard".to_string()]);
    session.stage5_command("conquest.start", vec!["Sabuk".to_string()]);
    session.stage5_command("conquest.owner", Vec::new());
    let missing_event_packets =
        session.stage5_command("event.spawn", vec!["MissingMonster".to_string()]);
    assert!(missing_event_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));
    let event_packets =
        session.stage5_command("event.spawn", vec!["BugBat".to_string(), "1".to_string()]);
    assert!(!event_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));
    let missing_hero_packets = session.stage5_command("hero.behaviour", vec!["2".to_string()]);
    assert!(missing_hero_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &not_found_message
    )));
    session.stage5_command("hero.recruit", vec!["Aide".to_string()]);
    let hero_behaviour_packets = session.stage5_command("hero.behaviour", vec!["2".to_string()]);
    assert!(!hero_behaviour_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::Chat { .. })));
    let failed_craft_packets = session.stage5_command("craft", vec!["crafted-blade".to_string()]);
    assert!(failed_craft_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat { message, .. } if message == &crafting_failed_message
    )));
    assert!(!session
        .world_snapshot()
        .inventory_items
        .iter()
        .any(|item| item.key == "crafted-blade"));
    session.stage5_command("mine", vec!["3".to_string()]);
    session.stage5_command("craft", vec!["crafted-blade".to_string()]);

    let snapshot = session.world_snapshot();
    assert_eq!(snapshot.stage5_systems.conquest.castle_owner, "BichonGuard");
    assert_eq!(
        snapshot.stage5_systems.conquest.active_wars,
        vec!["Sabuk".to_string()]
    );
    assert!(snapshot
        .stage5_systems
        .conquest
        .event_log
        .iter()
        .any(|entry| entry.contains("Event spawned")));
    assert_eq!(
        snapshot
            .stage5_systems
            .hero
            .as_ref()
            .map(|hero| hero.name.as_str()),
        Some("Aide")
    );
    assert_eq!(
        snapshot
            .stage5_systems
            .hero
            .as_ref()
            .map(|hero| hero.behaviour),
        Some(2)
    );
    assert_eq!(snapshot.stage5_systems.profession.ore, 2);
    assert!(snapshot
        .stage5_systems
        .profession
        .crafted_items
        .contains(&"crafted-blade".to_string()));
    assert!(snapshot
        .inventory_items
        .iter()
        .any(|item| item.key == "crafted-blade"));
}

#[test]
#[allow(deprecated)]
fn stage5_event_spawn_uses_nearby_spawnable_tile_on_crystal_map() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let _ = session.transfer_map("crystal:0:330:270");
    let before_count = session
        .app
        .world()
        .iter_entities()
        .filter(|entity| {
            entity
                .get::<DisplayName>()
                .is_some_and(|name| name.value == "BugBat")
        })
        .count();

    session.stage5_command("event.spawn", vec!["BugBat".to_string(), "1".to_string()]);

    let snapshot = session.world_snapshot();
    assert!(snapshot
        .stage5_systems
        .conquest
        .event_log
        .iter()
        .any(|entry| entry.contains("Event spawned 1x BugBat")));
    assert!(snapshot
        .entities
        .iter()
        .any(|entity| entity.name == "BugBat"));
    assert_eq!(
        session
            .app
            .world()
            .iter_entities()
            .filter(|entity| {
                entity
                    .get::<DisplayName>()
                    .is_some_and(|name| name.value == "BugBat")
            })
            .count(),
        before_count + 1
    );
}

#[test]
fn fishing_packets_toggle_crystal_update_surface() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    assert!(session
        .handle_packet(ClientPacket::FishingCast { cast_out: true })
        .is_empty());

    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    assert!(session
        .handle_packet(ClientPacket::FishingCast { cast_out: true })
        .is_empty());
    equip_crystal_item(&mut session, "BlueFishingRod", EquipmentSlot::Weapon);
    add_inventory_crystal_item(&mut session, "FishBait", 31);
    let object_id = current_player_object_id(session.app.world()).expect("player object id");
    let fishing_point = {
        let location = current_location(session.app.world());
        offset_point(&location.position, location.direction, 3)
    };
    let rod_current_dura = mir2_game_data::crystal_item_by_name("BlueFishingRod")
        .expect("BlueFishingRod template should exist")
        .durability
        .saturating_sub(1);

    let cast_packets = session.handle_packet(ClientPacket::FishingCast { cast_out: true });
    assert_eq!(
        cast_packets,
        vec![
            ServerPacket::DuraChanged {
                unique_id: 0,
                current_dura: rod_current_dura,
            },
            ServerPacket::FishingUpdate {
                object_id,
                fishing: true,
                progress_percent: 0,
                chance_percent: 28,
                fishing_point: fishing_point.clone(),
                found_fish: false,
            },
        ]
    );

    let auto_packets =
        session.handle_packet(ClientPacket::FishingChangeAutocast { auto_cast: true });
    assert_eq!(
        auto_packets,
        vec![ServerPacket::FishingUpdate {
            object_id,
            fishing: true,
            progress_percent: 0,
            chance_percent: 28,
            fishing_point: fishing_point.clone(),
            found_fish: false,
        }]
    );

    let reel_packets = session.handle_packet(ClientPacket::FishingCast { cast_out: false });
    assert_eq!(
        reel_packets,
        vec![ServerPacket::FishingUpdate {
            object_id,
            fishing: false,
            progress_percent: 100,
            chance_percent: 28,
            fishing_point,
            found_fish: false,
        }]
    );
}

#[test]
fn fishing_tick_reels_loot_and_autocasts_after_found_fish() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    equip_crystal_item(&mut session, "BlueFishingRod", EquipmentSlot::Weapon);
    add_inventory_crystal_item(&mut session, "FishBait", 31);
    add_inventory_crystal_item(&mut session, "FishBait", 32);
    add_inventory_crystal_item(&mut session, "FishBait", 33);
    let fish_index = mir2_game_data::crystal_item_by_name("SwordFish")
        .expect("SwordFish template should exist")
        .item_index;

    super::set_runtime_tick(session.app.world_mut(), 58);
    session.handle_packet(ClientPacket::FishingCast { cast_out: true });
    let mut tick_packets = Vec::new();
    for _ in 0..4 {
        tick_packets = session.tick();
    }
    assert!(tick_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::FishingUpdate {
            fishing: true,
            progress_percent: 100,
            found_fish: true,
            ..
        }
    )));

    let reel_packets = session.handle_packet(ClientPacket::FishingCast { cast_out: false });
    assert!(reel_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GainedItem { item } if item.item_index == fish_index
    )));
    assert!(reel_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::FishingUpdate {
            fishing: false,
            progress_percent: 100,
            found_fish: false,
            ..
        }
    )));

    super::set_runtime_tick(session.app.world_mut(), 57);
    session.handle_packet(ClientPacket::FishingCast { cast_out: true });
    session.handle_packet(ClientPacket::FishingChangeAutocast { auto_cast: true });
    for _ in 0..4 {
        session.tick();
    }
    let autocast_packets = session.tick();
    assert!(autocast_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GainedItem { item } if item.item_index == fish_index
    )));
    assert!(autocast_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::FishingUpdate {
            fishing: true,
            progress_percent: 0,
            chance_percent: 28,
            found_fish: false,
            ..
        }
    )));
}

#[test]
fn fishing_cast_requires_crystal_rod_bait_hook_and_fishing_cell() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    assert!(session
        .handle_packet(ClientPacket::FishingCast { cast_out: true })
        .is_empty());

    equip_crystal_item(&mut session, "BlueFishingRod", EquipmentSlot::Weapon);
    assert!(session
        .handle_packet(ClientPacket::FishingCast { cast_out: true })
        .iter()
        .any(|packet| matches!(
            packet,
            ServerPacket::Chat {
                chat_type: ChatType::System,
                ..
            }
        )));

    add_inventory_crystal_item(&mut session, "FishBait", 31);
    session
        .app
        .world_mut()
        .resource_mut::<FishingResource>()
        .rod_has_hook = false;
    let hook_packets = session.handle_packet(ClientPacket::FishingCast { cast_out: true });
    assert!(hook_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            ..
        }
    )));
    assert!(session
        .world_snapshot()
        .inventory_items
        .iter()
        .any(|item| item.name == "FishBait"));

    {
        let mut fishing = session.app.world_mut().resource_mut::<FishingResource>();
        fishing.rod_has_hook = true;
        fishing.fishing_attribute = -1;
    }
    assert!(session
        .handle_packet(ClientPacket::FishingCast { cast_out: true })
        .is_empty());
    assert!(session
        .world_snapshot()
        .inventory_items
        .iter()
        .any(|item| item.name == "FishBait"));
}

