#[test]
fn request_info_packets_return_crystal_map_monster_and_npc_data() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let map = crystal_respawn_manifest()
        .maps
        .into_iter()
        .find(|map| map.map_index >= 0)
        .expect("crystal respawn manifest should include maps");
    let monster = crystal_monster_manifest()
        .monsters
        .into_iter()
        .find(|monster| monster.monster_index >= 0)
        .expect("crystal monster manifest should include monsters");
    let npc = crystal_npc_info_manifest()
        .npcs
        .into_iter()
        .find(|npc| npc.npc_index >= 0)
        .expect("crystal npc info manifest should include npcs");

    let map_packets = session.handle_packet(ClientPacket::RequestMapInfo {
        map_index: map.map_index,
    });
    assert!(map_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::MapInformation { info }
            if info.map_index == map.map_index && info.file_name == map.map_file_name
    )));

    let monster_packets = session.handle_packet(ClientPacket::RequestMonsterInfo {
        monster_index: monster.monster_index,
    });
    assert!(monster_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::NewMonsterInfo { info }
            if info.name == monster.name && info.image == monster.image
    )));

    let npc_packets = session.handle_packet(ClientPacket::RequestNpcInfo {
        npc_index: npc.npc_index,
    });
    assert!(npc_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::NewNpcInfo { info } if info.name == npc.name && info.image == npc.image
    )));
}

#[test]
fn relationship_packets_emit_crystal_hint_and_update_surfaces() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let face_player_message = mir2_game_data::localized_text_or_fallback(
        super::current_language(session.app.world()),
        "server.FacePlayerForMarriageRequest",
        "server.FacePlayerForMarriageRequest",
    );
    let marriage_packets = session.handle_packet(ClientPacket::MarriageRequest);
    assert!(marriage_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            message,
            chat_type: ChatType::System
        } if message == &face_player_message
    )));

    let allow_packets = session.handle_packet(ClientPacket::ChangeMarriage);
    assert!(allow_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            ..
        }
    )));

    let divorce_packets = session.handle_packet(ClientPacket::DivorceRequest);
    assert!(divorce_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            ..
        }
    )));

    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        stage5.stage5_systems.relationship.pending_request_from = Some("Beloved".to_string());
    }
    let reply_packets = session.handle_packet(ClientPacket::MarriageReply {
        accept_invite: true,
    });
    assert!(reply_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::LoverUpdate {
            name,
            map_name,
            married_days,
            ..
        } if name == "Beloved" && !map_name.is_empty() && *married_days == 0
    )));

    let divorce_reply_packets = session.handle_packet(ClientPacket::DivorceReply {
        accept_invite: true,
    });
    assert!(divorce_reply_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::LoverUpdate {
            name,
            map_name,
            married_days,
            ..
        } if name.is_empty() && map_name.is_empty() && *married_days == 0
    )));
}

#[test]
fn mentor_packets_emit_crystal_hint_and_update_surfaces() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });

    let self_mentor_packets = session.handle_packet(ClientPacket::AddMentor {
        name: "Scout".to_string(),
    });
    assert!(self_mentor_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            ..
        }
    )));

    let allow_packets = session.handle_packet(ClientPacket::AllowMentor);
    assert!(allow_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::Hint,
            ..
        }
    )));

    let cancel_empty_packets = session.handle_packet(ClientPacket::CancelMentor);
    assert!(cancel_empty_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            ..
        }
    )));

    {
        let mut stage5 = session
            .app
            .world_mut()
            .resource_mut::<Stage5SystemsResource>();
        stage5.stage5_systems.mentor.pending_request_from = Some("Master".to_string());
        stage5.stage5_systems.mentor.pending_request_level = 40;
    }
    let reply_packets = session.handle_packet(ClientPacket::MentorReply {
        accept_invite: true,
    });
    assert!(reply_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::MentorUpdate {
            name,
            level,
            online: true,
            mentee_exp: 0,
        } if name == "Master" && *level == 40
    )));

    let cancel_packets = session.handle_packet(ClientPacket::CancelMentor);
    assert!(cancel_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::Chat {
            chat_type: ChatType::System,
            message,
        } if message.contains("cooldown")
    )));
    assert!(cancel_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::MentorUpdate {
            name,
            level: 0,
            online: false,
            mentee_exp: 0,
        } if name.is_empty()
    )));
}

#[test]
fn item_rental_packets_confirm_records_rented_item_and_binds_loan_payload() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let starting_gold = session.world_snapshot().gold;

    assert!(session
        .handle_packet(ClientPacket::ItemRentalRequest)
        .iter()
        .any(|packet| matches!(
            packet,
            ServerPacket::ItemRentalRequest { name, renting: false }
                if name == "Crystal Partner"
        )));
    assert_eq!(
        session.handle_packet(ClientPacket::ItemRentalPeriod { days: 7 }),
        vec![ServerPacket::ItemRentalPeriod { days: 7 }]
    );
    let deposit_packets = session.handle_packet(ClientPacket::DepositRentalItem { from: 4, to: 0 });
    assert!(deposit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::DepositRentalItem {
            from: 4,
            to: 0,
            success: true
        }
    )));
    assert!(deposit_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::UpdateRentalItem {
            loan_item: Some(item)
        } if item.unique_id == 4
    )));
    assert!(!session
        .world_snapshot()
        .inventory_items
        .iter()
        .any(|item| item.key == "dagger"));

    let fee_packets = session.handle_packet(ClientPacket::ItemRentalFee { amount: 100 });
    assert!(fee_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::LoseGold { gold: 100 })));
    assert!(fee_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ItemRentalFee { amount: 100 })));
    assert_eq!(session.world_snapshot().gold, starting_gold - 100);

    session.handle_packet(ClientPacket::ItemRentalLockFee);
    let lock_item_packets = session.handle_packet(ClientPacket::ItemRentalLockItem);
    assert!(lock_item_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::CanConfirmItemRental)));

    let confirm_packets = session.handle_packet(ClientPacket::ConfirmItemRental);
    let loan_rental_info = confirm_packets.iter().find_map(|packet| match packet {
        ServerPacket::UpdateRentalItem {
            loan_item: Some(item),
        } => item.rental_information.as_ref(),
        _ => None,
    });
    let loan_rental_info = loan_rental_info.expect("confirm should expose bound rental item");
    assert_eq!(
        loan_rental_info.binding_flags,
        super::CRYSTAL_RENTAL_BINDING_FLAGS
    );
    assert_eq!(loan_rental_info.owner_name, "Scout");
    assert!(loan_rental_info.expiry_binary_datetime != 0);
    assert!(confirm_packets
        .iter()
        .any(|packet| matches!(packet, ServerPacket::ConfirmItemRental)));
    assert!(confirm_packets.iter().any(|packet| matches!(
        packet,
        ServerPacket::GetRentedItems { rented_items }
            if rented_items.len() == 1
                && rented_items[0].item_id == 4
                && rented_items[0].item_name == "Dagger"
                && rented_items[0].renting_player_name == "Crystal Partner"
    )));
    assert_eq!(session.world_snapshot().gold, starting_gold);
    let snapshot = session.world_snapshot();
    assert_eq!(snapshot.stage5_systems.item_rental.record_count, 1);
    assert_eq!(
        snapshot.stage5_systems.item_rental.rented_items[0].item_name,
        "Dagger"
    );
    assert_eq!(snapshot.stage5_systems.item_rental.fee, 0);
    assert!(!snapshot.stage5_systems.item_rental.gold_locked);
    assert!(!snapshot.stage5_systems.item_rental.item_locked);

    let rented_items = session.handle_packet(ClientPacket::GetRentedItems);
    assert!(matches!(
        rented_items.as_slice(),
        [ServerPacket::GetRentedItems { rented_items }]
            if rented_items.len() == 1 && rented_items[0].item_name == "Dagger"
    ));
}

#[test]
fn item_rental_cancel_returns_deposit_and_refunds_locked_fee() {
    let mut session = SimulationSession::new(SimulationConfig::default());
    session.handle_packet(ClientPacket::StartGame { character_index: 0 });
    let starting_gold = session.world_snapshot().gold;

    session.handle_packet(ClientPacket::ItemRentalRequest);
    session.handle_packet(ClientPacket::DepositRentalItem { from: 4, to: 0 });
    session.handle_packet(ClientPacket::ItemRentalFee { amount: 100 });
    session.handle_packet(ClientPacket::ItemRentalLockFee);
    let active_snapshot = session.world_snapshot().stage5_systems.item_rental;
    assert_eq!(
        active_snapshot.partner_name.as_deref(),
        Some("Crystal Partner")
    );
    assert_eq!(active_snapshot.fee, 100);
    assert_eq!(active_snapshot.days, 1);
    assert_eq!(
        active_snapshot.deposited_item_name.as_deref(),
        Some("Dagger")
    );
    assert!(active_snapshot.has_deposited_item);
    assert!(active_snapshot.gold_locked);
    assert!(!active_snapshot.item_locked);
    let cancel_packets = session.handle_packet(ClientPacket::CancelItemRental);

    assert_eq!(cancel_packets, vec![ServerPacket::CancelItemRental]);
    let snapshot = session.world_snapshot();
    assert_eq!(snapshot.gold, starting_gold);
    assert_eq!(snapshot.stage5_systems.item_rental.record_count, 0);
    assert!(snapshot.stage5_systems.item_rental.partner_name.is_none());
    assert!(snapshot
        .inventory_items
        .iter()
        .any(|item| item.key == "dagger"));
    assert!(session
        .handle_packet(ClientPacket::GetRentedItems)
        .iter()
        .any(|packet| matches!(
            packet,
            ServerPacket::GetRentedItems { rented_items } if rented_items.is_empty()
        )));
}

